local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.speech
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.speech = text
end
local rows = text.values
rows["420:489959725"]="토리움 형제단에 대해 들어본 적 있나요? 검은바위 나락하지만 믿으세요, 우리는 그들처럼 전혀 없습니다.$b$b그 악당들은 너무 깊게 파묻고 지금은 더 어두운 세력에 봉사하고 있습니다. 라그나로스, 불의 주인. 우리는 의지와 목적에 대해 더 독립되어서 행복하지만 대부분의 경우 우리의 목적은 그들이 초래하는 모든 문제를 예방하는 것입니다."
rows["420:727991870"]="루비 드래크는 피해를 줄이고 동맹을 보호하는 데 탁월합니다.\010화를 붓는 분노를 사용하여, 그들은 물적 불의 흐름을 흡입 할 수 있습니다.\010류비 드레이크 는 적 공격 으로 인해 손상 될 때마다 피난 기하 를 얻는다. 이 기하 는 일련 의 피난 기하 을 수행 하기 위해 사용될 수 있으며, 드레이크 는 임시 에 들어오는 공격 과 주문 을 피할 수 있게 한다."
rows["420:991471165"]="잘 들어서 앉으세요 시간이 걸릴 수도 있습니다$B$B우리가 이 얼어붙은 지옥에 처음 도착했을 때, 알로스 장군은 발리언스 포지션에서 나와 비행하는 용기자 그룹에게 특별한 임무를 주었습니다. 얼라이언스 작전들을 위한 전진 공군 기지를 설립하기 위해서요.$B$B이 비행장이 그 결과였죠. 이 모든 악귀들과 얼어붙은 땅이 너무 단단해졌지만, 우리는 성공했고, 우리는 빨리 성공했습니다."
rows["421:140784265"]="내가 뭘 찾고 있는지 알고 싶니? 난 그 걸 좋아해요. 강하고 용감한 사람을 찾고 있어요. 뇌는 한 가지지만,$b$b어색한 암흑철 왜곡자들이 공격할 때마다, 그들에게 잔을 던질 수 있습니다.$b$b네가 떨어뜨린 모든 왜성에게 표를 붙여줄게"
rows["421:1674135233"]="파라곤의 힘은 강력한 마조입니다. 그들은 구루바시 제국 마조입니다. 우리는 Zandalar 마조를 얻어야 합니다. 부족은 우리의 마조를 가져갈 것입니다.$B$B ⁇ 루루브에는 세 종류의 파라곤이 있습니다. 동전을 찾아 보석들을 찾아 원시품을 찾아 파라곤입니다.$B$B지금  ⁇ 루브로 가서 죽여 Power의 Paragons를 데려와 부족으로 데려와 우리의 존경심을 얻어라"
rows["421:536791377"]="지옥의 종을 불러내는 비밀을 가르쳐야 한다면, 당신은 크로시우스를 파괴하고 그의 화상 유해에서 지옥의 핵을 가져오셔야 합니다. 하지만, 이것은 들릴 만큼 쉬운 일이 아닙니다. 크로시우스는 거의 완전히 태워버렸습니다. 당신은 그의 시체를 다시 불태우고 그 잔해에서 그를 부활시켜야 합니다.$B$B내 임프시, 임프시, 당신을 당신의 길로 인도할 것입니다."
rows["422:1047757883"]="어떤 사람들은 그들의 행동으로 경험의 쌓을 것을 멈추고, 지금 있는 힘의 수준에서 영원히 유지되고, 더 강해지지 않으려고 합니다.$B$B저는 이것을 가능하게 할 수 있습니다. 물론 수수료에 대 한.$B$B하지만 이 사실을 이해해줘, 일단 돈을 지불하면 더 이상 경험은 없어$B$B만약 당신이 나중에 생각을 바꾸고 다시 경험을 쌓고 싶다면, 같은 수수료로 그 과정을 취소할 수 있습니다."
rows["422:1335163221"]="바리안과 저는 오늘 이 자리에 그의 결정 전에 평화의 가격에 대해 긴 시간 이야기했습니다. 호드 아즈하라의 목재 사용이 포기되면 잿빛 골짜기 자원을 재빨리 씹는 거로 보면 얼마나 오래 지속될지 알 수 있을 겁니다.$b$b이 평화를 지지하지만, 대왕의 신뢰를 공유하지 않는다. 만약 호드가 다시 우리를 공격하기 위해 조약을 깨면..."
rows["422:1988912500"]="내가 알고 있는 건, 필사자, 나는 여기 꽤 많은 변명을 포기하고 있어,$B$B아탈알의 잠수한 성전 안에서 얻은 당신의 소유가 나를 위해 온다는 것을 알기 때문에 분명히 왔어요. 이 목적은 내 동료를, 내 형제를,"
rows["423:1064978564"]="그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다. 그 해적 은 그 해적 을  ⁇ 다.$B$B우리는 이제 해안에 있고 곧 니젤 포인트 마을을 향해 공격할 것입니다. 하지만 우리와 성지 사이에 많은 위험이 있습니다. 그리고 저는 황폐가 우리를 삼킬까 두려워합니다.$B$B지금 이 글을 쓰고 있는건 우리 처지에 대해 알고 언젠가는 우리를 망한 물의 악마들에게 복수할 것이라는 희망입니다."
rows["423:1300875672"]="계속 저널을 통해 훔친 상자를 찾는 데 도움이 될 수 있는 정보를 찾고 있습니다.$B$B책 마지막 페이지에 붉은 연필로, 이 페이지 옆에는 제임스의 표기판이 있습니다. \"스톤 케어런 호수 근처의 오래된 집...$B$B이 곳에 상자가 있는 것으로 추정할 이유가 없지만 다른 단서가 없는 것 같습니다."
rows["423:843004474"]="그래서 다른 아이들은 신을 용이해서 제이드 마녀의 문에  ⁇ 을 건드렸지만 그는 그렇게 하지 않더군요.$b$b신은 물러났지만, 나 아닌 누군가가 그를 도발한 거고 신도 도발한 거에서 벗어날 수 없어$b$b그는 문을 두드러졌지만 무슨 일이 있었는지 알 수 없었어요. $b$b난 신..."
rows["423:844033101"]="훌륭한 질문! 우리는 여기 페어에서 판매하는 많은 물건을 가지고 있습니다. 음식이나 음료에 관심이 있다면, 스탬프 또는 실리아니아의 부드를 방문하십시오.\010좀 더 외래적인 물건을 사면 라라가 당신을 위한 것 같을 겁니다. 그녀는 전 세계의 희소품에 전문적이죠.\010여기 어딘가에  ⁇ 이 달려가고 있어요. 잡을 수 있다면, 그는 던지기 위해 공을 팔고,"
rows["424:1132312628"]="필사자 여러분, 이 곳을 포위하는 끔찍한 부패로부터 저를 해방시켜주셔서 감사합니다. 아직 완전히 회복되지 않았지만,\010저는 당신과 당신의 친구들에게 자연의 회복탄력성을 부여해, 마법과 효과로부터 얻은 손상을 증가시키고 치유를 증가시킬 수 있습니다. 또한, 저는 정신의 Wells를 불러일으킬 수 있습니다."
rows["424:1500484710"]="내 마스터 모티스는 정말 전문가이지만 내가 아는 걸 공유할 수 있습니다.$b$b새 들 은 새 들 이 아닙니다. 물론, 새 들 은 날고, 날개 들 은 깃털 의 모양 을 하고, 심지어 우리는 그들을 호랑이 라고 부르기도 하지만, 새 들 과 비교 하는 것 은 여기서 끝난다. 사실, 그들은 용 들 과 더 많은 공통점을 가지고 있는 것 같습니다."
rows["424:1776034214"]="동부 왕국에서는 절대 없을 겁니다.$B$B그것은 칼림도어 어딘가에있을 것입니다, 하지만 여전히 호드 및 다른 인종에서 충분히 멀리.$B$B아마 보호받는 곳이 될 것 같네요 밸리나 크레이터 같은 곳이죠"
rows["425:339909786"]="제 뒤에  ⁇ 자 제단이 있습니다.  ⁇ 자라족이 신성한 장소입니다. 우리는  ⁇ 자라족이 있는 이 곳에서 기도합니다.$B$B즈울거루브에서 찾을 수 있는 하카리 비주스를 파괴하는 제단을 사용하여 부족에게 자신을 증명하십시오. 또한, 나는 당신이 즈울거루브에서 찾을 수 있는 동전의 세트를 위해 우리의 부족이 사용하는 명예 토큰을 교환 할 것입니다."
rows["425:561254889"]="운영: Gnomeregan은 여러 단계로 나뉘어 있습니다.$B$B먼저, 우리는 공중탑을 다시 가져야 합니다. 이것은 우리의 비행기가 우리가 Gnomeregan의 주요 입구로 이동하는 동안 공중 지원을 제공 할 수 있도록 합니다.$B$B또한, 근처 건물 중 하나에서 기계화된 전투복의 저장소가 발견되었습니다.$B$B그럼, 바로  ⁇ 마플러그로 갈게요."
rows["426:1271021636"]="알케미는 여러 가지 유용한 에릭시어, 액션, 오일, 플라스크, 카틀런을 만들기 위해 허브와 다른 재료를 사용할 수 있게 해줍니다. 또한 자신의 에릭시어와 플라스크를 사용하면 더 큰, 더 오래 지속되는 이점을 얻을 수 있습니다.\010고도로 숙련된 화학자들은 또한 다른 생산 직업에 사용되는 원자재와 특정 미네랄을 변환할 수 있습니다.\010알케미아는 식물과 잘 어울리죠. 왜냐하면, 그것은 여러분이 직접 식물을 수집할 수 있기 때문입니다."
rows["426:205256649"]="걱정 마, 내가 보이는 것 같지 않아$B$B내 이름은 아크리도스트라스스, 아크리드라고 부르지만 여왕이 네파리아인을 막으러 보내줬는데, 내가 맡은 일이 끝날 때까지 쉬지 않을거야.$B$B이 모든 것을 없애는 데 도움이 되시면 알렉스스트라즈의 호의를 받을 것입니다. "
rows["426:2110902811"]="스톡데스는 스톰윈드 시의 운하 구역 아래 숨겨진 고경호한 감옥 복합체입니다. 델워터 감독이 지휘하는 스톡데스는 작은 사기꾼, 정치 반군자, 살인자 및 이 나라의 가장 위험한 범죄자 수의가 있습니다. 최근에는 포로들이 주도하는 반란이 스톡데스 내에서 만화 상태에 이르게되었습니다. \010"
rows["427:2023637972"]="브리즈트!$B$B보안 레벨 치 터미널인 매트릭스 펀코그래프 3005 C 스트로크에 오신 것을 환영합니다.$B$B터미널 기능에 접근하기 위해 파란색 펀치 카드를 가져야 합니다.\01001010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000"
rows["427:428811417"]="젠타브라가 웃고 있습니다.$B$B다른 사람들은, 특히 시르발라, 이 계획에 별로 관심이 없었고, 그들은 여전히 우리가 한 번에 한 명만 일하기를 원하고, 동시에 모든 정신을 가지고 있지 않았습니다. 하지만 곤크는 손을 내밀고 있었고, 그들은 잘라잔이 통치할 때 섬들을 구하기 위한 유일한 방법이라고 알고 있었습니다.$B$B그놈도 다른 놈들을 별로 신경 쓰지 않았어."
rows["428:1211068895"]="칼리타, 다 끝났어, 사르센 돌은 완전히 충전되어 있고 이미 포털에서 에너지를 돌리고 있습니다. 당신은 아직도 그 많은 년 전에 내가 알고 있던 놀라운 수영자입니까? 돌은 악마나 우리의 \"사랑하는\" 여왕이 찾을 수 없습니다.$B$B칼리타, 호수의 바닥에 수영해, 중앙 아크 아래 깊이 묻고, 악마의 침입자들이 주변 성전을 파괴할 때 발견하지 못하기를 바랍니다."
rows["428:1828571767"]="어두운 곳을 찾아다니며 죽음의 담요의 수리법을 배웠습니다.$B$B이 옷은 주문기용으로 교환 가능한 에픽 옷입니다. 주문력, 속속 및 극대화을 부여합니다. 이 레시피를 가르쳐 줄 만한 사람을 찾고 있습니다.$B$B노스렌드에서 대부분의 임무를 완료하고 \"Loremaster of 노스렌드\"의 성과를 거둔 사람은 죽음의 담요의 레시피를 배울 가치가 있습니다."
rows["428:1847709428"]="네, 말론은 달의 여신인 밤 엘프들이 '엘루네'라고 부르는 여신과 동행했다. 그들의 연합에서 모든 드루이드들의 보호자 신인 아제로스.$B$B하지만 내 말 들어, 난 계속 돌아다닐 거야$B$B마롤은 자연의 놀라운 힘이지만, 그는 치명적인 인종과 "
rows["428:2093868401"]="Kun-Lai 정상에서 빈 마을의 Jin'yu는 오늘 물과 이야기했습니다. $b $b 아마 이미 알고 있을 겁니다 하지만 척추고래는 꽤 공격적인 물고기입니다.  $b $b 만약 그 분노한 짐승들을 잡을 수 있다면, 그들의 취약한 생태계에 균형을 회복하는 데 도움이 될지도 모릅니다."
rows["428:367013450"]="에비아나는 그날 전투장에서 죽었지만, 필사적 종족과 남은 고대인들은 결국 승리했습니다. 첫 번째 드루이드는 그녀의 시체를 살인의 가운데 발견하고,$B$B그녀는 이 성당 바로 바깥에, 신성한 돌의 한 구경 안에 안장되었다.$B$B가한의 씨앗이 세계 나무를 심는데 사용되었고, 그 신성한 영역의 남은 것은 그것뿐이었는데, 그 씨앗은 그 성지 안에서 사라졌습니다."
rows["428:550096783"]="울두마는 창조자들에 대한 연구 시설이며, 아제로스의 생물권 향상을 위한 지속적인 노력이다. 울두마에 관한 그들의 작업에 관한 구체적인 정보는 그들의 디스크 세트에 울두마의 판을 보유한 개인에게 제한된다.$B$B울담 복합 내부의 데이터 저장소는 특정 실험과 데이터 컴파일링을 처리하도록 프로그래밍되었습니다. 자세한 정보는 이들을 참조하십시오."
rows["428:929082511"]="믿기지 않을 거야, 난 중앙 DMZ에서 순식간에 탐사 작전을 하고 있었는데 호드 윙 커맨더, 멀버릭, 이치만과 슬라이도르 모두를 죽여라 분노가 나를 잡았고 날개인 사람으로부터 나 떨어져서 그 선보이는 뮬버릭을 몰아넣었다$B$B기지로 돌아가야 돼!"
rows["428:955193532"]="언젠가 내 친구한테 메시지를 전달할 수 있겠어$B$B<이트리그는 잠시 머리를 숙이고 마치 기도하는 것처럼>$B$B랜드와 그의 형제 마임은 스파이어를 통치했고, 암흑 철의 왜들과 끊임없이 갈등을 빚어 도시 상부 지역에 왜들을 몰아넣는 데 성공했으나 용들이 왔을 때만 마임이 죽은 후에야"
rows["429:1056492251"]="네, 아니, 지금은 악마일 수도 있지만 티루스 블랙홀은 한때 밤의 엘프였죠.$B$B그는 그의 주인 패배 후 포로로 잡혔고, 여기 정상에 갇혔습니다. 그의 불멸의 형태는 신성한 에너지로 묶여있죠.$B$B하지만 아마도 그의 영혼의 가장 희미한 빛은 여전히 불타는 것 같지만 적어도 우리가 확실히 알아내야 합니다."
rows["429:1320888069"]="친구, 내가 가진 건 이같은 돌파구인데, 아직까지 볼 수 없는 걸로 팔아먹는 거야$b$b보시다시피, 나는 완벽한 사람을 찾기 위해 타버너에서 돈을 쓰는 것을 지쳤어요. 그래서 나는 이 안경을 만들었습니다. 그리고 이제 모든 사람이 순수한 완벽처럼 보입니다.$b$b이거 좀 시도해 주면 좋겠소"
rows["429:1491447922"]="보시다시피, 저는  ⁇ 의  ⁇ 이 있는 한 명입니다. 암흑 철의 왜자와 라그나로스의 잡지에 있는 짐승들의 힘은 저를 혼자 압도할 것입니다. 하지만 저는 당신 같은 용감하고 야심찬 모험가에게는 카들론의 주민들을 다루는 데 아무런 문제가 없을 것이라고 확신합니다. 당신이 저를 도울 것을 선택한다면, 저는 당신의 가장 야만적인 꿈보다 더 많은 부와 부를 보상합니다."
rows["429:446332811"]="군인에게 죽이는 법을 가르쳐도 안 돼, 하지만 죽이고 싶어하는 법을 가르쳐도 안 돼. 그건 우리가 걱정할 필요가 없는 일이야. 내 모든 남자들은 우리에게 한 짓 때문에 그 나가에서 한 조각을 빼내기를 기다릴 수 없어.$B$B표면과 접촉하는 방법을 찾아야 하지만 그 전에 나가들과 조금 접촉하고 싶어"
rows["429:479291285"]="울두아르의 기록은 로켄이 우리에 대항해 도시 자원을 사용하지 않도록 필요한 지식을 가지고 있을 수 있습니다. 문제는 그 기록의 열쇠가 분산되어 숨겨져 있다는 것입니다.$B$B제가 발견한 것 같습니다. 이 조각 중 하나는 발명가의 도서관에서 있습니다. 이 곳은 북동쪽 산의 북쪽 끝에 위치하고 있습니다."
