rows["42:882550790"]="내가 묻었지, 호드의 영혼은 누구인가?"
rows["42:883059903"]="스팀어의 길에서 훈련을 찾습니다."
rows["42:890494104"]="그럼 나한테 메시지를 전달해줘?"
rows["42:891747643"]="위치로 들어와, 발사 준비됐습니다."
rows["42:893079111"]="카릴은 방 곳곳에 파란색 촉매를 던집니다!"
rows["42:893427091"]="트롤은 악인이라고 들었어요"
rows["42:895277594"]="오웃사이더, 우리를 괴롭히기 위해 왔어?"
rows["42:896424077"]="오, 어서요, 하루종일 이런 일을 해왔어요!"
rows["42:897688040"]="'유가 너를 쳐다보며$B$B내가 알아?"
rows["42:898087914"]="이제 당신은 우리와 함께 해야 합니다. 영구적으로!"
rows["42:899435595"]="저게 죽음의 함정이야"
rows["42:902142637"]=" ⁇ 어,  ⁇ 어, 그레고르"
rows["42:914337907"]="내 마을에 오줌을 치는 법을 가르쳐줄 거야!"
rows["42:914454507"]="9~10... 준비됐든 아니든, 여기가 내야!"
rows["42:916696048"]="베개! 누가 우리 베개를 훔쳐 갔어!"
rows["42:917665589"]="그럼요. 제가 관여하지 않는다면요."
