rows["42:923446016"]="방탄장치 부위가 고장됐어 시스템 탈하"
rows["42:923783338"]="카발은 그들의 무분별함을 갚을 것이다!"
rows["42:925685321"]="물론이오, 그대여. 그럼 우리가 다시 만나는 날까지..."
rows["42:928979931"]="이건 쉬운 일이야, 다음 단서를 준비해"
rows["42:92909442"]="%s 바구니를 풀고 있는 동안 음향을  ⁇ 습니다."
rows["42:929577684"]="그럴 순 없어, 드르파 씨를 가질 수 있어"
rows["42:93152415"]="넌 절대 알 수 없는 힘이 있어, 말푸리온"
rows["42:932508720"]="서쪽 수렁에서 물을 끌어오도록 해라."
rows["42:932846653"]="[%s저는 라이트웰을 사용하지 않습니다."
rows["42:935268385"]="%s 은밀한 에너지의 출처를 찾습니다."
rows["42:935945145"]="넌 노예가 아니야 어떻게 여기 왔어?"
rows["42:935997863"]="왜 그들과 놀아다니?"
rows["42:937771945"]="배고픈 늙은이가 필요한 것 같아"
rows["42:938666683"]="진짜... 커다란 걸... 보여주겠다!"
rows["42:94688646"]=" ⁇ 한 Twilight에서 악마와 함께!"
rows["42:949323165"]="문에 들어가서 나 나가야 돼"
rows["42:951931346"]="넌 위대한 일을 할 거야, 연습생"
rows["42:954219911"]="네가 간청하는 걸 좋아하지만..."
rows["42:95851006"]="이런 일이 일어나지 않을 거야"
rows["42:959194"]="그만! 부메랑 그만 던지라고! 나 미안해! 나 일한다!"
rows["42:960124084"]="디스릭스, 웨스트리치 정상에 가야 해!"
rows["42:961715380"]="그 꿈 말입니다... 아주 황당한 꿈. 기억 안 나십니까?"
rows["42:965048535"]="너  ⁇ 다 여자아, 조그라로 돌아와!"
rows["42:979991511"]="정말 날 이길 수 있다고 믿나?"
rows["42:980529972"]="무슨 냄새가 났어?"
rows["42:984950508"]="의식에 대한 후퇴, 성모님 기다리고 있습니다."
rows["42:989535888"]="난 검은 용이야, 도움이 필요 없어"
