rows["42:997699507"]="제발 도와줘!"
rows["42:999827767"]="핀레이, 판매할 수 있는 물건 좀 봐"
rows["430:1151480047"]="내 팔이 불안해져, 불안한 기다림에 내 가축을 리치 왕트롤은 우리가 기다려야 하고 스컬지 계속 힘을 키워라!$B$B리치 왕의 위협을 종식하려면, 우리는 노스렌드로 항해하여 호드의 전력을 그에게 주어야 합니다! 우리 군대는 전염병과 침략으로 인한 사망에 대한 복수를 받을 준비가 되어 있고 기꺼이 있습니다.$B$B이제 공격할 때가 됐어!"
rows["430:1721810624"]="로르테마르는 신규 상태를 보고 싶으세요?$b$b이 실험은 시간 낭비라고 두 사람에게 말해야 합니다. 다른 생물들의 생명체를 노예로 삼아 힘을 얻었지요.$b$b이 길은 카엘타스 선스트라이더가 한 번 걸어갔던 길이고 우리 사람들을 거의 파괴시켰어"
rows["430:1757006321"]="'불'이 가장 좋은 말이 아닐 수도 있어요.$B$B이 생물은 뜨거운 불꽃의 마그마에 살고 있지만 불에 의해 한 잔도 손상되지 않습니다!$B$B만약 내가 이 짐승들 중 한 마리에게서 원숭이 피부를 찾을 수 있다면, 에버룩에 있는 나의 귀여운 친구인 마리푸스 다크하머에게 돌려보내면, \010"
rows["430:2134742594"]="우리 \"선생 charms\" 프로그램을 알고 있었나요?$B$B나 같은 공식적인 크로운 이벤트 마스코트는 사랑스러운 매혹 컬렉터 키트를 배포할 권한이 있습니다.$B$B그 다음, 수집한 사랑스러운 매력을 사용하여 친구나 사랑하는 사람들을 위한 사랑스러운 매력을 위한 팔찌를 만들거나 사랑 토큰을 위한 사랑스러운 상인에게 넘겨주실 수 있습니다!$B$B가장 인기있는 활동 중 하나는 좋아하는 지도자들에게 팔찌를 만드는 것입니다. 그들이 존경받고 존경받는 것을 알려주는 것입니다."
rows["430:269796897"]="안녕하세요, 젊은여, 귀족한 영혼을 다시 만나서 좋네요.$B$B디레 마울, 옛적에 엘드레타라스라는 곳은 그 핵심까지 부패해져 있습니다. 저는 제 형제들이 어둠과 혼란의 힘에 휘말리는 것을 보았습니다. 많은 사람들이 이 장소를 땅에 찢어 버릴 것입니다.$B$B하지만 디레 마울은 살릴 가치가 있어, 필사자."
rows["430:575349596"]="필사자 여러분, 이 곳을 포위하는 끔찍한 부패로부터 저를 해방시켜주셔서 감사합니다. 아직 완전히 회복되지 않았지만,\010난 당신과 당신의 친구들에게 폭풍의 분노를 줄 수 있어, 당신의 피해와 최대의 건강을 증가시킬 수 있고, 만약 당신이 파괴될 수 없을 정도로 악의 대상이 된다면,"
rows["431:240360773"]="이 작업장은 내 작업장이 아닙니다. 하지만 어느 날 훈련이 끝나면 저는 발명가가 될 것입니다.$B$B그런데, 그는 오래전에 고대의 트롤 유적들을 연구하러 갔는데, 그는 계속 얘기하고 있었습니다.$B$B타나라신, 테네케리스, 타나라니사니?$B$B<Liv은 머리를 흔들고 있습니다.>$B$B아니, 그게 아니죠..."
rows["431:900186047"]="이제 내가 어떻게, 어디서, 언제 Sulfuras Eye를 얻을 수 있는지에 대한 기술적인 정보를 알려주지 않을거야. 난 당신이 그 것들을 알아낼 것이라고 확신합니다. 이 계약을 서명해 주세요."
rows["432:198511238"]="죽음의 날개, 또는 한때 그가 알려진 네르타리온은 세계의 힘을 구현한 측면이었습니다. 이 필사적 영역에 대해 거의 무한한 힘을 부여한 타이탄 형상자 Khaz'goroth: 세계의 가짜로 알려진$B$B배신과 속임수를 통해, 악인은 다른 네 가지 측면을 설득하여 악마 영혼으로 알려진 물체를 그들의 힘으로 심하게 약화시켜 한때 위대한 측면들 사이에서 분열을 강요했습니다. \010"
rows["432:669059798"]="왜 이 햇볕이 잘 드는 해안과 결정 파란 물에서 떠나고 싶지는 모르겠어요. 여기 아래는 천국이네요. 하지만 제 동생 제펫타에게 말해주세요. 그는 이미 하루 종일 티리스팔에 갇혀있다는 것에 대해 이미 너무 화를 내리고 있습니다. 이 제펠린은 오그리마로 떨어지기 때문에 당신은 그의  ⁇ 을 듣고 걱정할 필요가 없습니다. 하지만 당신이 곧 티리스팔에 있다면, 내 경고를 듣고 시작하지 마십시오."
rows["433:2143979096"]="저는 모든 집집이나 제작 직업의 기초를 가르쳐 줄 수 있지만, 그뿐입니다.\010연습생의 실력을 배우는 데는 한 직업에만 종사하는 전문가를 방문해야 합니다.\010두 가지 직업까지 배울 수 있습니다. 두 가지 집집, 두 가지 생산, 또는 각각 한 직업.\010고고학, 요리, 초상급, 낚시 같은 부차적 인 기술들은 두 직업에 포함되지 않습니다."
rows["433:680475044"]="왕자의 불멸의 생명과 거의 무한한 힘을 보존하기 위해 사람들이 파괴되었습니다. 수천 명의 분할된 힘은 이제 왕자와  ⁇ 드라라라르 열호들에게 유도됩니다. 남은 몇 명의 생존자들은 임몰타를 감옥에 두기 위해 직접 기둥에 힘을 공급하고 있습니다.$B$B악마가 그 구속을 풀면, 그 악마는 그 때 큰 아카나 요새의 작은 남은 것을 파괴할 것입니다."
rows["434:1665219246"]="믿거나 말거나, 그녀의 계획은 효과가 없었어요. 그녀는 계란을 얻었고,$B$B그러다 죽음의 날개가 알게 됐어$B$B그는 레아스트라사라는 배드랜드의 동굴에 갇혀서 그녀의 모든 작품과 함께 파괴했습니다.$B$B한 가지, 정화된 검은 용 계란은 분비되어 숨겨졌습니다!"
rows["434:704062707"]="바르고트 대장님이 바르고트 대장에게 바르고트 대장에게 바르고트 대장에게 피의 엘프 공격에서 도망쳐달라고 명령하셨어요$B$B나는 바로 앞 가장자리에 걸어 불타는 군단 악마들이 막대를 빼앗았지만, 나는 목숨을 구해 버렸어$B$B비록 제 주인은 제 실패에 대해 아무것도 모르지만 여전히 부끄러워합니다."
rows["435:101128655"]="이것은 믿을 수 없습니다! 당신은 강력하고 독성적이고 환상적인 병에 덮여 있습니다. 이 원정 샘플을 채취하도록 허락해 주십시오. 저는 여러분의 동맹국들로부터도 계속되는 감염을 제거하고, 의학의 이름으로 여러분의 용기와 희생을 보상합니다.\010[앞으로도 진행하기 전에, 모든 공격 멤버들이 근처에 있는지 확인해 보세요.]"
rows["435:957576266"]="특히 냄새가 나기 쉬운 물고기 들 은 열대 해수 를 좋아하는 물고기 들 이다. 그 중 가장 냄새가 나기 쉬운 물고기 들 은 줄루브의 증기 물 에서만 발견 될 수 있다.$B$B쥬리아의  ⁇ 스쿠크들은 가흐란카를 그 곳으로 끌어들였다고 생각합니다. 트롤들은 아마 그가 그들의 신 중 한 명이라고 말할 것입니다.$B$B믿으세요, 하지만 제 명단을 지으세요. 제 매력을  ⁇ 리안  ⁇ 스 ⁇ 스랑 채워주세요. 그 늙은이가 올 겁니다."
rows["436:1739147242"]="아, 자에터 <셀레브라스>은 눈을 돌린다$B$B내 아버지 레무로스는 그를 막으려고 노력했어요$B$B자에타르는 거침없는 사람이었고, 흙의 초자연 공주에게 사랑에 빠졌을 때, 아버지는 그들의 연합이 저주된 것을 알았지만, 자에타르는 듣지 않았다.$B$B켄타우르는 그의 실수로 태어났습니다. 그들은 변형되어 증오가 많았어요. 제 삼촌 자에타르는 그의 친척들에 의해 살해당했습니다.$B$B악의 왕자녀 테라드라스는 여전히 그의 유물을 크리스탈 동굴에서 보호하고 있습니다."
rows["436:400660144"]="하지만, 우리 세상 의 용 들 은 수천 년 동안 살 수 있지만, 이 불 호랑이는 짧은 생애 를 거쳐 달걀 에서 성인 으로서 죽음 으로 빠르게 이동 합니다.$b$b비록 제 주제가 우리의 공부와 감정적인 연결을 하지 말라고 경고하긴 하지만, 가끔은 그들을 위해 미안해하지만, 그들은 살아서 너무 밝게 불어오지만, 죽음에서, 그들은 빨리 대체되고 잊혀집니다."
rows["436:529018685"]="전쟁 시대에 라제리히 디프일러는 카자크 신사의 중 가장 무서운 부교수로 봉사했다. 레지옹이 패배하고 카자크가 다시 오염된 흉기로 강제되었을 때, 라제리히는 그의 주인으로부터 불어난 땅을 확보하도록 위탁받았다.$B$B얼라이언스는 불타진 땅 이외의 영토에 대해 호드와 소규모 전투를 벌였지만, 라제리흐는 다른 그림자 협의회 세파와 그 나라의 잔인한 드레드마울 오그를 통합했다."
rows["436:676188744"]="이 섬에서 우리가 직면한 모든 것 보다 훨씬 더 강한 Kil'jaeden의 수비자들은 이 섬에 있습니다. 레지온은 심지어 우리의 아카네 수호자 기술을 Fel 에너지로 왜곡하여 훨씬 더 악의적인 것을 창조했습니다. 그 Sunblade 보호자들 중 한 명이 내 군대를 십분화시켰고, 나는 빠른 후퇴를 명령했습니다. 나는 내 부대가 완전히 고원에서 밀어질 것으로 예상했지만 적은 쫓아내는 것을 중단함으로써 나를 놀라게했습니다."
rows["437:1054586005"]="다크셔의 북부 지역에서는 클립스프링 강이 흐르고, 현재 펠우드라고 알려진 땅으로부터 내려오고 있다. 강이 흘러내리고 메구즈 에드 로 빠져나오면서, 바다의 가장 깊은 부분들이 시작되는 곳으로 북쪽으로 이동한다. 일부 사람들은 그 모양으로 인해 돌 갈고리를 부르는 석조 형성은 당신이 찾고 있는 것을 찾을 수 있습니다.$B$B경고해 주세요. 돌고래에 있는 추첨자들이 모여 그들의 영토를 침범하는 사람들을 공격할 것입니다."
rows["437:1241687741"]="저주의 제단에서 서서 저주받은 자들의 영혼들이 기도하며 무릎을 꿇는 것을 보면, 내가 구단 옆에 서 있는 것을 보지 못합니다.$B$B오로노크가 주면$B$B내가 많은 걸 알고 있다고 말했잖아 그 중 하나가 구단 중위였어$B$B난 평생 끔찍한 일을 해왔어 남녀를 죽였어$B$B오로노크는 그의 말들로 질식한다."
rows["437:1586766831"]="이것이 우리의 마지막 입장입니다. 여기서 일어나는 일은 시대를 거쳐 계속 이어질 것입니다. 그 결과는 무엇이든, 우리는 명예로 싸웠다는 것을 알게 될 것입니다.$B$B영웅, 두려움이 이 황폐한 방에서 가장 큰 적인 기억해줘 너의 마음을 굳게 하라 그리고 네 영혼은 천 개의 태양보다 더 빛나는 빛을 낼 것이다 빛 선행이 그들을 덮어"
rows["437:648435764"]="우리는 섬에 있는 동맹국의 도움을 필요로 합니다.$B$B제인타브라는 이미 몇 년 전부터 섬의 동물들을 지켜왔고, 우리는 그녀의 도움과 동물들의 도움을 필요로 합니다.$B$B부원스미디는 섬에서 죽은 자들의 영혼을 통제하는 강력한 왕이고 그의 축복은 우리의 공격에 결정적입니다.$B$B동맹국들이 우리와 함께하면, 자라잔과 그의 정신 통제 트롤 군대는 기회가 없을 것입니다."
rows["437:828402724"]="에테리움은 내 고향인 카레쉬의 에테리얼의 지배적 계급이었습니다. 비극적으로, 우리는 비공개의 주인 디멘시우스가 그의 비공개 군대를 세계로 내보내기 직전에 카레쉬를 탈출하도록 강요당했습니다. 그리고 그의 길에 있는 모든 것을 완전히 십분화했습니다. 이 행위로 인해 에테리움은 복수를 맹세했습니다. 그들은 그 이후로 디멘시우스를 추적하고 있습니다.$B$B하지만 보호국은 디멘시우스에 대한 반응이 아니라, 우리는 이더리움에 대한 반응이었습니다."
rows["438:1294760044"]="불모의 땅은 한때 풍성한 숲이었는지 아십니까? 수천 년 전, 첫 번째 산더링 이전, 그것은 녹색하고 번영적이었고, 칼도레이족이 감시했습니다. 그러나 대륙이 찢어지고 이 땅이 우리가 부르는 칼림도어로 분리되었을 때, 이 자연의 계곡은 가혹하고 햇볕이 불어진 평야가 되었습니다.$B$B제가 처음 이 사실을 알게 되면서, 저는 이 일을 큰 비극으로 보았고, 숲을 다시 재배하는 방법을 찾기로 결심했습니다."
rows["438:662149602"]="네 눈빛을 보고 있어 난 네 사람들의 감정을 모르는거라고 생각하지 마 난 경비원이나 시민의 불신적인 시선을 당할 때도 불편해$B$B난 바리안에게 대한 의무 때문에 여기 있어 얼라이언스 내 사람들을 치료해야 했지$B$B이제, 당신이  ⁇ 을 끝냈다면, 스컬지는 스톰윈드에서 모든 것을 엉망으로 만들고 있습니다. 왜 당신은 그것에 대해 뭔가를하지 않는가?"
