rows["43:789727441"]="데피아즈단의 또 다른 승리가!"
rows["43:790252342"]="%s의 총에 있는 연기를 불어넣는"
rows["43:79506097"]="당신이 뭘 위해 서있는지, 당신은 다시 일!"
rows["43:795753205"]="아버지, 그 사람과 대화하는게 무슨 의미가 있을까요?"
rows["43:800214288"]="어서, 이 바보야. 영원히 살고 싶지 않아?"
rows["43:805395859"]="%s은 공격의 미묘한 에너지를 흡수합니다."
rows["43:806812168"]="내가 다 잡았어!"
rows["43:811585728"]="정말, 파티에서요, 꽤 아름답습니다."
rows["43:812847958"]="네 명의 죄수 모두 구출됐어!"
rows["43:814106271"]="그쪽을 순찰하고 발견하는 걸 보고하도록 하라!"
rows["43:814285574"]="어쩌면 내가 여기 온 게 잘못됐을지도 몰라"
rows["43:824419815"]="당신은 젠다라르와 모고 둘 다 이길 수 없습니다!"
rows["43:82500362"]="여기 제가 찾고 있던 스케치가 있습니다."
rows["43:825702058"]="침입자, 왕좌의 경호자, 깨어!"
rows["43:82720982"]="그래서 그 모든 잡음을 일으키는 건 당신들이야!"
rows["43:828183120"]="내가 명령받은 대로 하고 있었어요"
rows["43:82884087"]="하루 종일 스파링을 해봤는데 언제 먹죠?"
rows["43:829064958"]="모든 게 잘 될거라고 확신합니다."
rows["43:83415865"]="쾅! 쾅! 쾅! 지금 자동차를 개조하는 중이오!!!"
rows["43:840694434"]="이제 제더스 상자를 파괴하고 제더스 상자!"
rows["43:842648062"]="이제 갈 수 있어?"
rows["43:84743008"]="오,  ⁇ ... 안녕하세요."
rows["43:850908728"]="%s는 바닥을 조사하고 승인을 주며"
rows["43:856902150"]="지구가 당신을 데려갈 수 있도록 허락해..."
rows["43:868948639"]="대부분의 사람들이 흔들리는 곳, 당신은 극복했다."
rows["43:870306817"]="내가 잃을 줄 알았어 강이 말했지"
rows["43:871215028"]="저 마차가 또 고장 났나, 사무엘?"
rows["43:877310664"]="적어도 우리는 우리의 죽음을 얻을 것입니다!"
rows["43:877745013"]="우리가 마지막으로 만난 이후로 정신이 약해졌어"
rows["43:882151657"]="다 드라카리 제국은 내 불만을 용납하지 않을거야!"
rows["43:88545903"]="스푸터발프 넌 천재야 30."
rows["43:889717072"]="%s는 스트랑글스톤밸리 낚시 여행을 계획하고 있습니다."
rows["43:890055086"]="내가 말한 걸 알아요, 내 신뢰는 잘못됐어요"
rows["43:891654015"]="붉은십자군이 이 땅을 정화할 것이다!"
rows["43:895327420"]="도와줘요, 저 가난한 첼시"
rows["43:897239096"]="쉬고 있어, 방랑자 우리 불은 네 거야"
rows["43:902486061"]="움직여라, 경비병들! 신나게 썰어 봐라!"
rows["43:90694934"]="페어 스테이징 지역으로 가는 여행은 다음과 같습니다."
rows["43:912045255"]="%s은 그 기원을 찾아내게 되었습니다."
rows["43:914703551"]="살려면 나와 함께 오세요"
rows["43:917320620"]="달리아를 혼내주러 왔군. 구경 좀 해도 되겠지?"
rows["43:917418086"]="<아동이 궁금해서 쳐다보며>"
rows["43:917673543"]="줄을 막아!"
rows["43:921331510"]="우리 인생에, 우리는 말할 수 없는 비극을 겪었습니다."
rows["43:923459835"]="형제들아, 굳건히 서라 출혈!"
rows["43:924018827"]="T.A.D 부대는 우선 목표가 있습니다!"
rows["43:929028008"]="...그리고 당신은 마스터의 증오에 빠져들게 될 것입니다."
rows["43:932590793"]="병사 세오릭, 키트린, 블리드, 아그몬드"
rows["43:941499346"]="오커스를 순수 섬으로 데려갈래?"
rows["43:949362564"]="이 책의 페이지들은 파괴되었습니다."
rows["43:95070671"]="더 좋아서, 여기서 나가자!"
rows["43:95132642"]="잘 싸워, 그리고 당신의 사람들에게 명예를 가져오세요!"
rows["43:952732905"]=" ⁇ 펜에 타고 나가를 먹어라!"
rows["43:967231563"]="내 귀여운 아이들아... 먹이가 아주 많구나!"
rows["43:968406833"]="번개를 불러야 한다고 강요하지 마!"
rows["43:969300439"]="잘 쏘았어 $p방패가 약해지고 있어요"
rows["43:971594278"]="미안하오, 자매여. 그리 염려할 바는 아니오."
rows["43:972734822"]="영혼의 힘이 그를 찢어 버립니다!"
rows["43:979343166"]="이  ⁇ 을 치세요 얼라이언스 배에서  ⁇ 어들!"
rows["43:985485267"]="언젠가는 너도 수뽀송피부 될 수도 있어. 좋지?"
rows["43:986736870"]="내 명상을 방해해줘"
rows["43:987680150"]="일어나라, 형제들이여. 적들을 물리쳐라!"
rows["43:993967563"]="야롱올은 나쁜 놈이라고 들었어요"
rows["43:994008752"]="오, 그냥  ⁇ 잠만 하고 있어"
rows["43:997130645"]="이제 타운이온박스까지 올라갈 거야"
rows["440:2038714741"]="사트라스 시의 승리 소식이 빠르게 퍼져나갔고, 이전 전쟁과 새로 시작된 전쟁에서 난민들이 도시로 쏟아져 나왔다.$B$B이리던에서 휴식을 취하는 사람은 거절당하지 않습니다. 그래서 당신은 불쾌한 인물을 만나게 될 수도 있습니다. 하지만 대부분, 그들은 모든 희망을 잃었고 이제 새로운 삶을 누렸던 평범한 사람들입니다."
rows["440:853903201"]="이 힘들은 하이번의 마법을 유지해 줄 것이고, 엘드레타라스의 벽 안에 있는 사람들이 그들의 끝없는, 점점 더 증가하는 마법의 고통을 먹여줄 수 있게 해 줄 것입니다.$B$B수천 년이 지나면서 엘드레'타라스 내의 삶을 유지하면서 임모를'타르를 감옥에 갇히게 하는 데 필요한 힘은 변화하기 시작했습니다. 임모를'타르를 묶는 데 드는 비용은 에너지를 흡수하고 분배할 수 있는 속도를 덮어버렸다. 한때 순이익은 손실로 변했습니다."
rows["441:1813220602"]="Fanglords가 죽었어 모든 희망은 사라지지 않았어$b$b하지만 깨어날 수 있는 의식은 매우 복잡합니다. 혼자서는 할 수 없습니다.$b$b난 필요한 모든 준비를 처리할거야 하지만 네가 날 보호해 줄 필요가 있어 나라렉스의 에메랄드 드림 여행에서 불러온 악몽은 꽤 무서운 것으로 밝혀지네$b$b날 방어할 준비가 되면, 말해주세요. 나랄렉스의 방으로 가는 길을 안내할게요."
rows["441:1931845049"]="안녕하세요, 여러분 같은 모험을 추구하는 사람에게 제안이 있습니다.$B$B제 발명품인 슈퍼 에그 오 매틱과 함께 저는 히포그리프들을 구하기 위한 캠페인을 위해 드루이드들에게 열심히 일하고 있습니다. 새들은 페라라스의 유적에 거주하는 고르도니 오그르의 악영향에 영향을 받고 있으며, 그들의 수가 감소하고 있습니다.$B$B난 다양한 종류의 달걀을 수집하고 있어"
rows["442:1206624026"]="네가 이해하지 못해 내가 원한다면 이 동굴에서 탈출할 수 있어$B$B내 아버지  ⁇ 소크가 죽은 사람들로부터 돌아왔지만, 그는 같지 않다.$B$B그는 수천 년 전 고대 전쟁 때 목숨을 바쳤다.$B$B마침내 그들은 실패한 세계 나무인 보드라시를 재배시키기로 결정했고, 그 마법으로 아버지를 다시 데려오기로 결정했습니다."
rows["442:1602334969"]="당신은 Kil'sorrow 요새의 Kil'sorrow 오크가 그들의 기지를 공격했다고 믿게 하는 일련의 사건을 연출할 것입니다 그리고 또 다른 일련의 사건은 Warmaul 오크가 Kil'sorrow 오크가 그들의 기지를 공격한다고 믿게 할 것입니다.$B$B이렇게 하면 우리 두 가지 문제를 해결해 줄 수 있을 거야$B$B보더피스트는 그들의 영토를 되찾고 당신의 사람들은 보더피스트, 워마울 그리고 그림자 협의회로부터 공격을 받지 못할 것입니다."
rows["442:1794554638"]="<Vol'jin은 그의 비웃음을  ⁇ 어내는 얼굴에 미소를 짓게 한다.>$b$b아직은 안 돼, 소문을 듣고, 귀신 이야기를 하고, 올 볼진이 돌아와서 쫓아다니는 것 같군$b$b그가 빨리 알아내면 너무 아쉽지만 내가 거기 있을 수 없어 그의 비만하고  ⁇ 은 눈을 볼 수 있어"
rows["442:291762482"]="보라, 강한 자가 진동하여 그들의 발 앞에 엎드려서, 그들이 자기 말을 할 수 없도록 두려워하였더라$B$B그러나 여전히 이  ⁇ 라타인 들, 이 존재하지 않는 종교 를 숭배 하는 척 하는 자 들 은 그들의 '신'을 통제 하는 헛된 시도 로 필연적 인 것 을 역설 하였다.$B$B하지만 한 사람은 어떻게든 살아남았고, 그의 미쳤던 상태에서"
rows["442:444032780"]="어릴 적 다크셔의 야간 엘프로서, 저는 악어마을 해머로 알려진 불쾌한 개인들과 교류했습니다. 그들 중 한 그룹은 저와 친구가 되었고, 부끄러움하게도, 저는 엘루네에 대한 믿음을 피하고,$B$B엘루네에서 비전이 내게 왔을 때까지는 내가 옛 신들의 추종자로서 쓰러진 불쾌함을 깨어나지 못했다.$B$B회개로, 엘루네에게 기도한 대로 일하기 시작했어요. "
rows["442:547875442"]="12천 년 전 밤 elf 마법사의 비밀 세트 에 의해 건설 된 고대 도시 엘드레'타라스 는 아즈하라 여왕 의 가장 소중한 미묘한 비밀을 보호하기 위해 사용 되었다. 세계 대 황폐화로 인해 파괴되었지만, 이 놀라운 도시의 상당 부분이 여전히 강렬한 디레 마울 으로 서 있다. 폐허의 세 개의 다른 구역은 모든 종류의 생물들이 침투했습니다. 특히 유령 고위, 불쾌한 풍자리 및 잔인한 오그라들. \010"
rows["443:1818098204"]="헤메트는 내가 아는 가장 위대한 사냥꾼입니다. 우리는 아제로스 몇 달 전에 윈터스프링의 언덕에서 우연히 서로를 만났어요. 그와 나는 같은 돌고래를 추적하고 있었습니다.$B$B사냥꾼을 위해 싸우기보다는, 그 돈을 내기로 했습니다. 얼음의 칼을 수집한 사람이 다른 사람에게 무언가를 요구할 수 있게 되었죠.$B$B피츠처럼 보이시나요?"
rows["443:188184279"]="우리 는 약 6 개월 동안 이렇게 하고, 그 집 이 끔찍한 변화 를 겪는 동안 지켜봤습니다. 불쾌 한 괴물 들 은 마음대로 숙소 를 돌아다니고 있었습니다. 어두운 종파 들 은 의식 과 희생 에 관한 여러 가지 물건 들 을 매장 했습니다. 우리 는 더 이상 숨길 수 없다는 걸 알고 있었습니다.$B$B그들이 예상대로 우리를 발견하고 잡았고, 우리 옷을 벗고 피를 흘린 채로 내놓았고, 우리는 며칠 동안 헐벗고 공포를 떨고 앉아 있었습니다."
rows["443:272066281"]="여러분 모두 그러한 조직을 할 수 있다는 것은 예상치 못한 일입니다. 얼라이언스와 호드 모두 아안키라지 전쟁에 대한 준비를 완료했습니다. 우리가 지금 이 순간에도 자료는 실리투스로 배송되고 있으며 모든 것이 하루 안에 도착해야 합니다. 그러면 이동 모래의 왕자리를 다시 집어 넣으려는 사람이 스카라브 데이스의 둥지를 때리고 아안키라지의 문들을 열어야합니다. 그때 전쟁이 정말로 시작됩니다."
rows["443:948067774"]="당신도 나도 상상할 수 없죠. 영혼이 몸에서 찢어지는 때 어떤 사람이 겪는 고통을요. 그들은 죽지 않고 살아있지 않습니다.$B$B이 땅들의 악마의 주자인 라제리히 주제는 그들을 모두 노예로 삼아 9개를 자기에게 맡겼고 암흑문 근처에 묶음돌을 두었다 나머지 9개는 그의 하위원들 사이에 나뉘었다."
rows["444:134203029"]="맞아요, 롱브로우 계열의 마지막 멤버입니다.$B$B안타깝게도 그는 구  ⁇ 과 같은 물질로 만들어지지 않은 것 같네요.$B$B이모가 자신의 이름과 그에 따른 책임은 그에게 무거운 짐을 짊어지고 있다는 것을 약점으로 받아들이지 마세요.$B$B언젠가는 그가 이해하게 될 거야 가끔은 네가 사랑하는 것 때문에 싸워야 한다는"
rows["444:1367038748"]="오그릴라에 온 신인인으로서, 당신은 이 곳의 크리스탈에 충분히 노출되어 있지 않아서 그 모든 혜택을 누릴 수 있습니다.$B$B반면에 우리는 아주 오래 전부터 이곳에 왔습니다. 그래서 여러분이 상상할 수 있듯이 우리는 많은 것들에 대해 꽤 잘 알고 있습니다.$B$B최근 우리는 동조 수용소들의 악마에 대해 많은 관심을 가지고 있습니다. 더 구체적으로, 우리는 그들을 영원히 없애는 방법을 생각해냈습니다.$B$B적어도 이론은 이렇습니다."
rows["444:2016959442"]="난 발랑트 선장의 우리시스 랙모어이고, 이건 내 운명된 배의 마지막 날들의 기록입니다.$B$B우리는 재료를 한 배로 피더문 강성으로 항해하고 있었는데 나가들이 갈랑트의 부위를 공격하면서 그들을 몰아냈지만 그들이 돌아올 줄 알았어요. 가장 소중한 사물들을 잃는 것을 두려워해서"
rows["444:753133470"]="이 이론은 당신이 어디에 있든 거대한 폭발로 완전히 파괴하고 그 입자를 차원적 찢어지기를 통해 보내고 여기에 기계에 다시 삽입한다는 것입니다. 인스턴트 운송! 그것은 항상 작동하지 않을 수도 있지만, 당신은 어떤 종류의 괴물 엔지니어입니다! 생존이 당신의 최우선 과제로 있다면 당신은 결코 진정한 괴물 엔지니어가 될 수 없습니다!\010여기 이 지형 찢어지기 만들 수 있는 레시피가 있습니다.\010"
rows["445:162108509"]="약 5개월 전 벤처 코의 스트랑글스톤 부문은  ⁇ 티 베이에서 크랭크 피즐레불이라는  ⁇ 한 상인으로부터 독을 손에 넣었습니다. 피즐레불은 자니질에게 독을 훔쳤던 것 같습니다.$B$B네, 배척자 잔실 - 네크로맨시에서의 그의 '실험'의 특성 때문에 자신의 부족에서 추방된 트롤$B$B물론, 독이 들어간 후에 서로가 독을 시험해봤습니다. 그 결과는 재앙이었습니다."
rows["445:2006093641"]="네가 준비한지는 아직 보여야 한다. 가장 지혜롭고 나이가 많은 드루이드들도$B$B내 말을 들어왔으니 이제 계속 가야 한다 내가 가르쳐준 걸 지켜야 한다. 너의 힘이 시험될 때가 있을 것이다. 곰처럼 네 적을 견디어야 한다."
rows["445:999439336"]="그것은 비밀과 힘에 대해 이야기했고 또한 진실에 대해 이야기했습니다. 빛 아니었지 포세이큰 오크들이 오래전부터 드레네에 대항해 사용했던 펠 에너지는 우리를 침투시켰고 빛우리 몸의 부패에 책임이 있는 것과 같습니다.$B$B하지만 우리의 정신은 깨지지 않았고, 공기는 내 백성을 구출할 수 있는 다른 길을 제시했습니다.\010"
rows["446:1485630488"]="모가들은 우리 사람들에게 거짓말을 하고, 우리가 그들의 창조라고 말하며, 우리의 육체를 현재의 형태로 변형시켰다고 말하며, 우리는 그들에게 존재할 것을 빚진다고 주장합니다.$b$b모구들에게 도전합니다. 그들은 우리 위에 아무런 힘을 가지고 있지 않습니다. 그들은 우리가 무엇을 보고, 어떻게 살고, 어떻게 느끼는지 알지 못합니다. 그들은 우리의 영혼에 볼 수 없습니다.$b$b크로스만이 당신의 영혼에 있는 것을 알고 있습니다. 크로스는 알고 있고, 크로스는 이해합니다. 크로스는 당신에게 힘을 줬습니다."
rows["446:1487252861"]="이 곳으로 온 이유는 썬더로드 클랜이라는 후진 문화에 대한 공부를 하기 때문이었습니다.$B$B그들은 약했고 마너로스의 피로 펠 오크로 변신한 힘의 유혹에 굴복했습니다.$B$B저는 그들의 모든 텍스트를 읽었습니다. 특히 저는 배구, 화살표, 그리고 태블릿의 유물을 발견하는 것에 관심이 있습니다."
rows["446:1608193218"]="간단히 말해서, 이것은 옳습니다.$B$B지구인들의 물리적 특징은 작은 몸매의 인형형이지만, 그들의 구성은 아제로스의 다양한 석기 핵 화합물이다. 그들의 디자인은 인지기능의 희생 없이 강도를 극대화하고 체력이다. 그들의 피부와 근육은 거의 물리 피해에 내성이 없으며, 매우 작은 수정으로 지구인들은 원치 않는 마력에 대한 놀라운 탄력성을 나타냅니다."
rows["448:2110494301"]="왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜$B$B고노메리건은 너무 오랫동안 우리의 계획의 핵무기 아래에서  ⁇ 어 버렸습니다. 방사능 폭탄의 폭발은 우리를 우리 도시를 떠나게 했지만, 이제 우리는 그것을 되찾을 기술을 가지고 있습니다!$B$B우린 우리의 것을 되찾고 테르마플러그를 법 앞에 내놓을 거야!"
rows["449:1223888761"]="사냥꾼처럼 반려동물도 전문성을 선택할 수 있습니다. 고양이와 같은 야만적인 반려동물은 피해를 줄 수는 있지만 잘 견딜 수 없습니다. 거북이와 같은 끈질긴 반려동물은 더 방어적이며 원격에서 머무르면서 적의 관심을 점유할 수 있습니다. 거미와 같은 현명한 반려동물은 공격과 방어 능력을 혼합하여 전투장 및 경기장에서 특히 유용합니다.$b$b반려동물마다 기본 전문품이 있지만, 원하는 경우 변경할 수 있습니다."
rows["449:1224135830"]="라스 프로스트비스퍼는 이 학교의 감독자이고, 모든 암흑 마스터들을 훈련시키는 책임자이고, 케일'투자드의 중장이자 유리한 학생이고, 한때 스트롬가르드의 헤지 마그였는데,$B$B켈'투자드가 종파를 열었을 때 라스는 그의 계열에 합류한 첫 번째 사람들 중 한 명이었다. 라스는 어두운 마술을 통해 그는 불멸을 찾을 것이라고 알고 있었다."
rows["449:1572696660"]=" ⁇ 고로에 있는 이 황새는 불모의 땅의 맹수들과 관련이 있는 것 같습니다. 매우 지능적이고 휘발성적이며 감각이나 행동 규범을 가지고 있습니다. 제가 만난 이들 중 가장 큰 것은 라르코비입니다. 그는 내가 본 적에서 가장 위험한 짐승 중 하나입니다. 타타헤어에서는 라르코비라는 말은 \" 날카로운 손톱\"을 의미하지만, 그것이 그에게 정의를 주지 않습니다.$B$B만약 당신이 그를 사냥할 계획이라면 라르코루이를 과소평가하지 말아요. 하지만 당신이 할 경우 내가 할 수 있는 모든 방법으로 도와드리겠습니다."
rows["449:2097579902"]="아름다운 아비아나, 새들의 주인! 아제로스의 날개로 된 모든 생물들은 그녀의 충성을 빚어졌어요. 특히 우리는 타롱의 드루이드입니다. 그녀의 은혜로 우리는 형태를 변화시키고 하늘을 향해 나아갈 능력을 부여 받았습니다.$B$B아비아나는 그녀의 자녀들 사이에서 셀 수 있는 큰 포식 새처럼 아름답고 끔찍했다. 그녀는 어머니 나무인 기하니르의 높은 영 영역에서 살았지만 아제로스에 큰 날개로 된 여신의 형태로 나타났습니다."
rows["449:839151057"]="여러분 모두 그러한 조직을 할 수 있다는 것은 예상치 못한 일입니다. 얼라이언스 과 호드 모두 아안키라지 전쟁에 대한 준비를 완료했습니다. 지금 우리가 말하는 동안에도 자료는 실리투스로 배송되고 있으며, 모두 $2113w 일 이내에 도착해야 합니다. 그러면 이동 모래의 막대기를 다시 집어 넣을 사람이 스카라브 데이즈의 둥지를 때리고 아안키라지의 문들을 열게 될 것입니다. 그때 전쟁은 진정으로 시작됩니다."
rows["44:1003461001"]="제발 깨지 마... 제발 깨지 마...."
rows["44:10039328"]="뭐, 더 나쁘게 죽었을 수도 있지."
rows["44:101013069"]="하하하! 저주받은 아가만드에 영원한 언데드의 고통을!"
rows["44:1010572742"]="정원 문은 바로 그 언덕 위에 있습니다."
rows["44:101376006"]="어디서 왔어요?"
rows["44:101651727"]="넌 아름다운 시야야야, 친구"
rows["44:1017743039"]=" ⁇ , 그건 거의 안 됐어"
rows["44:1020360265"]="잔나! 젠장, 이거 고쳐야겠어!"
rows["44:1022072675"]="이 겁쟁이들에게 전쟁의 진정한 의미를 가르쳐라!"
rows["44:1023290603"]="(Chaos, 미친 짓) 뇌를 포옹하는 것 처럼"
rows["44:1030687156"]="침입자, 침입자가 날 구하려고 애쓰고 있어!"
rows["44:1032915289"]="그걸 입는 건 다 잘 안 돼!"
rows["44:1033048444"]="악! 좋아, 이제 표적 신세는 사양하겠어!"
rows["44:1034997297"]="히포그리프 산을 오르내리고 전투를 준비하라!"
rows["44:1035084882"]="%s 그의 형태가 바뀌면서 울고 도망치고 있습니다."
rows["44:1037920656"]="아무것도 안 돼, 아가씨 괜찮은 건 다행이야"
rows["44:1039734403"]="야크 꼬리는 균형을 유지하는 데 도움이 되나요?"
rows["44:1039960989"]="아... 보이는 것보다 똑똑한 사람이야"
rows["44:1040103257"]="피와 번개의 의미를 가르쳐라!"
rows["44:1044050692"]="당신이 하는 모든 일은 호드에 의해 이루어져야 합니다."
rows["44:1044240477"]="<무르락은 목마른 눈으로 당신을 쳐다보고 있습니다.>"
rows["44:105123994"]="내 발톱은 널 찢어 버릴 거야"
rows["44:1055622648"]="이 도서관의 지식은 놀라운 것입니다."
rows["44:1058911268"]="통로를 통해 울리는 울음소리가 들려요!"
rows["44:1059047169"]="나 가야 돼 악의 자극이 잘 죽여라 오마리온"
rows["44:1060342517"]="너무 피곤해 잠시 쉬게 해"
rows["44:1061658895"]="증오가 나를 강하게 해치게 해"
rows["44:1071623555"]="병사 마커스, 트리메인, 오스구드, 램프렛..."
rows["44:1073596993"]="삐삐하고 반짝이는 소리입니다."
rows["44:1075160328"]="%s는 라그나로스에게 마지막 봉사를 합니다..."
rows["44:1076776920"]="난 칠면조 저녁식사처럼 요리됐다고 생각했어!"
rows["44:1083139620"]="안아... 안아...$b$b무슨 일이 벌어지고 있어요?"
rows["44:1084895985"]="목적지에 대한 안내가 필요하십니까?"
rows["44:1085601196"]="다음번엔 더 잘 준비해볼게요!"
rows["44:108797913"]="그는 수도원의 남쪽에 있다고 생각합니다."
rows["44:1091257828"]="더 나아가서 스톰피크스까지 갈 준비가 됐어요"
rows["44:1091950672"]="강을 찾아보겠습니다"
rows["44:1096722527"]="내가 돌아왔어... 주인님, 충성스러운 종님"
rows["44:1098195088"]="<킬라그]은 조용히 하라고 권합니다."
rows["44:1099021872"]="호드가 겨울손아귀 요새를 점령했습니다!"
rows["44:1099115145"]="우리 땅은 죽은 사람들로부터 안전하다고 생각했지?"
rows["44:1100955361"]="아, 똥구리, 넌 날 망칠거야!"
rows["44:1104393267"]="죽음의 소리... 귀에 너무 달콤한 소리..."
rows["44:1106572160"]="또 다른 스컬지 배트가 파괴되었습니다!"
rows["44:1108086661"]="너 같은 녀석들을 도저히 이해할 수 없더군. 영웅놀이나 하는 녀석들..."
rows["44:1110835606"]="<사제 이일디나라는 의심스러운 눈을 가지고 있다>"
rows["44:1112500095"]="%s 폭발성 미인을 초청하기 시작합니다!"
rows["44:1118851625"]="카가스 블레이드피스트는 쓰러졌어 호드!"
rows["44:1119235200"]="저도 개를 한 마리 기르고 있지만 검을 주지는 않아요."
rows["44:111945913"]=" ⁇ 은 호드을 떠났다고 들었어요"
rows["44:1119584194"]="%s 한 조각을 잡고 주머니에 넣는..."
rows["44:1124304629"]="이건 제가 부르는 작은..."
rows["44:1124608259"]="그 생물을 물리치면 우리 생물을 해방시킬 수 있어!"
