rows["44:986612943"]="나가 어둠의 왕자를 물리치"
rows["44:987719894"]="내가 언제 존중하지 않을까?"
rows["44:989388449"]="강아지들 환영받지 못해요 잘 자파를 받으세요!"
rows["44:993582754"]="자블리, 이 쓰레기를 청소하는 사람을 불러!"
rows["44:996577046"]="괴물이 죽었습니다! 이제 어둠골은 안전합니다!"
rows["450:793643212"]="고대 신은 실리시드의 원형으로부터 화신을 만들려고 했습니다. 이 화신들이 바로 퀴라지라고 알려져 있지요. 지능이 발달된 퀴라지는 어떤 목적을 가지고 자신들의 창조주의 이름을 지었습니다. 바로 크툰이 태어난 것이지요. 퀴라지는 이 세계가 자신들의 신을 배신하는 그날 세상을 파괴하기 위해 수천 년 동안 군대를 훈련시켜 왔습니다. 도시 전체가 하나의 거대한 요새인 안퀴라즈는 퀴라지가 자신들의 군대를 양성하고 크툰의 강림을 준비하기 위해 건설한 것이었습니다."
rows["450:869148004"]="죽음의 문은 불타는 군단가 개 개들을 키우기 위해 사용하는 세계로 열리는 포털입니다. 그 생물 중 하나를 볼 때마다, 그것이 어디에서 왔으며,$B$B최근 우리는 불타는 군단가 포털을 통해 이 생물들을 불러올 것을 강화했다는 것을 알게 되었습니다.$B$B불구속의 물결이 되기 전에 죽음의 문을 닫아야 하고 모든 것이 사라져버릴 거야!"
rows["451:1114342558"]="잿빛 골짜기년] 조람 스트랜드 일 인 블랙파토름 딥스는 한때 밤 엘프들의 달 신인 엘루네에 헌신된 영광스러운 사찰이었다. 그러나 위대한 선더링은 사찰을 찢어 씌워 베일드 바다의 파도 아래로 침몰했다. 그곳은 고대 힘으로 끌어당겨져 나가와 사타이르가 등장하여 그 비밀을 밝혀내기 전까지 그대로 남아 있었다. 전설은 고대 짐승인 아쿠마이 사찰의 유적 안에 거주했다고 한다. \010"
rows["451:1637611065"]="내가 있는 모든 것은 아타스에게 빚진 거야$B$B저는 포세이큰가 스컬지와 싸움을 노스렌드로 이룰 수 있는 시간을 갈망했습니다. 하지만 우리는 나머지 호드의 지원을 필요로 합니다. 우리 얼라이언스의 다른 인종들이 지원하지 않는 한 우리의 숫자는 크지 않습니다.$B$B아타스의 최근 공격 호드 스롤이 아이스크라운에 전쟁을 선포하도록 설득할 수 있을 것 같네요"
rows["451:312581667"]="어떻게 하면 신 들 이 이렇게 잔인 하게 나를 공격 할 수 있었을까요? 내가 소중히 여기는 모든 것 은 사라졌어요. 죽거나 파괴 되었어요. 숲 의 짐승 들 이 내 가족 을 빼앗아 갔습니다.$B$B난 깨진 사람이고, 깨진 섬에 갇혀있어요.$B$B내가 이 일을 해낼까? 빨리 해, 난 저항하지 않을거야. 내 목숨을 빼앗아, 낯선 사람, 내가 너무 겁쟁이. 내 손이 떨고... 칼은 맞지 않을거야.\010"
rows["451:396074398"]="라그나로스와의 전투에서 기회를 잡기 위해서는 화염된 타원지대에 기꺼이 용감하게 대처할 동맹군들을 모아야 합니다. 그리고 그러한 동맹군들을 우리 소장에 모집하기 전에 - 드루이드, 군인, 또는 단순한 공급자 -$b$b이 몇 개의 표지판을 가지고 있으면 우리 소리의 영웅이 될 수 있습니다 수백에 달하는 숫자를 모아 군대를 이끌게 될 것입니다$b$b계획이 보이시나요?"
rows["451:705329962"]="이 탑에 어떤 일이 있습니다. 저는 병에 걸렸고, 그 탑 근처에서 일하는 다른 벤처 코 직원들도 병에 걸렸습니다. 지난 주에 우리 두 명의 순찰자가 죽었고, 즉시 정신이 없는 드론으로 다시 살아왔습니다. 생명력은 제 몸에서 빠져나가고 있습니다. 나는 통제를 잃는 것을 느낄 수 있습니다. 권유가 지배하고 있습니다. 나쁜 충동... 아직은... \010"
rows["452:1748275224"]="대 십자군 재판은 십자군 재판의 더 어려운 버전이다. 모든 만남은 더 어렵고, 당신은 승리하기 전까지는 자유롭게 만남을 시도할 수 없을 것입니다. 50 실패한 시도 후, 대 십자군 재판은 일주일 동안 종료됩니다. 대 십자군 재판을 성공적으로 완료한 후, 당신은 보상으로 추가적인 추수 상자 보상을 받게됩니다. 당신은이 재판에 준비되어 있습니까?"
rows["452:184091569"]="명실상부하고 항상 중립적인 스팀위들 카르텔의 이름으로, 보그패들에서 환영합니다. 우리는 동부 왕국에서 유일한 해변 해변 휴양지와 군사적 수준의 무기 창고라는 자랑스럽습니다.$B$B남쪽에서 전쟁이 벌어지고 있지만, 이 벽 안엔 재미와 놀이도 있어, 좀 쉬고, R&R를 하고, 한두잔을 마시고,"
rows["452:239932782"]="암버 드레이크는 시간을 이용해서 피해를 잘 해준다.\010충격 로프 를 사용 하여 적 목표 를 둘러싼 시간 흐름을 방해 하고 즉시 손상 시킬 수 있다. 이 효과 의 힘 은 목표 에 있는 충격 충전 으로 인해 크게 증가 한다.\010황무색 드레이크 는 위협 을 받으면 적 들 의 시간 흐름을 잠시 중단 할 수 있습니다. 이 때 방해는 충격 충전 의 형태로 영향을 받은 목표물에 큰 양의 충격 에너지를 저장 합니다."
rows["452:638334653"]="도망치고 싶으면 괜찮지만 먼저 몇 가지 알아야 합니다$b$b트롤에서 멀리 떨어져 있어 널 죽일 게 아니라 함정에 빠뜨려 여기로 데려올 거야$b$b당신이 볼 수 있는 모든 랩터와 이야기해봐 새로운 능력을 가르쳐 줄 뿐만 아니라, 당신의 진전을 기억하고  ⁇ 루부에서 벗어나는 길을 훨씬 쉽게 만들 수 있게 도와줄 것이다.$b$b이미 다시 능력을 가지고 있어, 좁은 곳에서 벗어날 수 있어$b$b그리고 물에서 벗어나라$b$b행운을 빌어요"
rows["452:740756115"]="에테리움은 어두워지고... 왜곡되어 있다. 복수만이 그들의 유일한 수단이 되었다. 그리고 그들의 길을 걸거나 그들의 일에 참여하지 않는 모든 사람은 적으로 간주된다. 많은 사람들이 에테리움이 미친 짓으로 몰락하고 떠났다는 것을 보았다. 에테리움 협의회의 여러 넥서스 왕자들은 다른 목표를 가진 다른 그룹과 단파를 형성하기 위해 에테리움을 포기했다. 컨소시엄은 이러한 단체의 예 중 하나입니다. 보호국 또 다른 ... "
rows["452:745329002"]="레드 크레인과의 시간은 짧았지만 그의 지도하에 많은 것을 배웠습니다.$B$B이 적, 이 \"sha\" 에너지는 우리가 직면한 모든 것과는 다릅니다. 그것은 수백 년 동안 땅에 담겨있는 감정적 혼란의 물리적 표명입니다.$B$B이 감정적 인 에너지는 이제 살아 있는, 감성적인 숙주들을 찾아서 살고 있습니다.$B$B이 대선은 대륙 전체를 덮을 위협이 되고, 아마도 전 세계를 덮을 수도 있습니다. 우리가 파다레인을 상대로 대처하는데 도움을 주지 않는다면요!"
rows["453:1313756916"]="북파일론은 노란색, 빨간색, 녹색 결정들을 받아들이고 있습니다.$B$B이 연구결과에서, 이 연구결과에서 연구결과에 대해 살펴보면, 이 연구결과에서 연구결과에 대해 연구결과에 대해 연구결과에 대해 알아볼 수 있는 몇 가지 방법이 있습니다. $B$B크리스탈 충전에는 빨간색과 노란색의 크리스탈이 필요합니다. 이것은 큰 폭발을 일으키고, 적들을 놀라게 할 것입니다.$B$B크리스탈 리스터레이션에는 노란색과 녹색의 크리스탈이 필요합니다."
rows["453:1355274733"]="그 들 이 자라는 나무 는 열매 를 맺었다. 처음에는 효과가 있었던 것 같았지만, 우르소크 는 다시 돌아왔고, 잠시 동안 기쁨 으로 가득 차 있었습니다.$B$B회복되면서 그는 그 사람이 아니었고, furbolg도 아니었음을 알았습니다.$B$B고대 드루이드들이 폭라시를 무너뜨리는 악은 무엇이든 새로운 나무에서 나타나서 모든 것을 피를 흘리는 괴물로 바꿨습니다.$B$B지금 그리즐리 힐스를 걷는 건 내 아버지가 아니고, 안식을 가져야 합니다."
rows["453:1493879933"]="처음 도착했을 때, 저는 마을의 동명인 사람을 만나기를 희망했습니다.$B$B로즈엘레스는 돌아다녔다.$B$B대부분의 젊은 고래들은 연습생으로 취임할 때 '나는 장교가 되고 싶다'라는 단계로 넘어갑니다.$B$B솔직히 말해서 저는 파스트라이더의 시대를 지나지 못했어요. 아무도 꿰매기 전문가가 되겠다는 꿈을 꾸지 못했지만, 우리 엄마는 말했듯이 파스트라이더들이 벌거벗은 채 달릴 수는 없어요."
rows["453:1769065778"]="전 세계 각지에서 직원들의 다양한 조각들을 추적해 왔고, 그렇게 함으로써, Kel'Thuzad의 직원을 개혁하려는 계획을 발견했습니다. 그는 이미 직원들의 몇몇 조각들을 수집했습니다.$B$B수호자의 대인들을 켈'투자드의 손에 넣지 않는 것이 얼마나 중요한지를 충분히 강조할 수 없습니다. 솔직히, 대사적 규모의 재앙을 제외하고는 그 결과는 어떤지 모르겠습니다."
rows["453:771722865"]="당신이 여기 있다는 사실은 첫 번째 단계입니다. 당신이 원한다면 올바른 선택입니다.$B$B여러분들은 단지 개인적인 이익을 추구하기 위해 여기 있을 수도 있고, 혹은 도덕적으로 강요당하기 때문에 있을 수도 있습니다. 그 이유 중 어느 것도 그 자체로 중요하지는 않지만, 사실 둘 다 이 목적을 위해 결정적입니다. 에라니쿠스가 견디는 고통은 저를 제 꿈에서 벗어나게 해 주었습니다. 그리고 이제 그의 고문이 끝나게 되는 것이 제 책임입니다. 저는 지금 여러분께 이 탐구에 도움이 되길 부탁합니다.\010"
rows["454:1230522518"]="이 자료를 흡수하는 데 필수적인 것은 창조자들이 이 세상을 떠난 후 오랫동안 세계의 발전 순환의 필수적인 부분일 수 있는 인종을 합성하고자 한다는 것을 이해한다는 것입니다. 아제로스.  $B$B보조적인 참고로, 지대적 명칭은 창조자들에 의해 새로운 인종에 적합하다고 간주되었으며, 지대적 구성에 기초했다."
rows["454:1284512776"]="제 가슴은 기발한 디자인으로 2개의 열쇠가 필요해서 잠금을 풀 수 있습니다. 금과 은의 열쇠입니다.$B$B하지만 우리는 그들을 잃게 될 것이 되어 있었습니다. 다음 나가 공격 때 제 열쇠가 사라졌고, 그 다음 날 드립 매크루라가 우리를 공격하고 그를 깊은 곳으로 끌어들였을 때 제 첫 부하가 사라졌습니다.$B$B나가와 마크루라는 열쇠를 가지고 있다고 확신합니다. 저는 둘 다 적이기 때문에 그들을 공유하지 않을 것입니다."
rows["454:40054892"]="파일론은 어딘가에 데이터를 전송하고 있는 것 같습니다.$b$b기둥을 자세히 살펴보면, 붉은, 파란색, 녹색의 결정들이 특정한 형식으로 배치된 작은 테이블을 발견하게 됩니다.$B$B큰 붉은색의 결정의 원은 양쪽에서 작은 파란색의 결정과 녹색의 결정의 원이 접한다.$B$B당신 은 발견 한 것 에 대해 듣기 위해 누군가 의 관심 을 많이 가질 수 있다는 것을 알고, 그 들 이 보는 것 을 주의 깊게 관찰 합니다."
rows["455:1850156010"]="역의 기계가 그를 다시 집어넣어 \"생명\"으로 데려왔다.$B$B그리고 이제, 감사의 표정으로, 그는 우리 모두를 \"육체의 저주\"라고 부르는 것에서 치유함으로써 은혜를 돌려주려고 했습니다.$B$B메카조드 (Mechazod) 의 말에 따르면, 이것은 결국 타이탄들의 모든 창조물에 닥치는 상태입니다. 다른 말로, 우리는 모두 일종의 로봇으로 시작해서 수천 년 동안 서서히 육신적인 존재로 변합니다.$B$B말도 안 되는 건 알아요"
rows["455:860443803"]="얼마 전 이 곳은 끔찍한 전투의 장소였는데, 우리는 네더가르드와 아르헨티나 아브란스는$B$B그 시절은 어두운 날이었는데, 피 흘리고 절망에 가득했습니다.$B$B하지만 아제로스의 왕국들은 곧 우리와 함께하여 괴물을 밀어붙였다!$B$B이 캠프는 이제 조용하지만, 난 여기서의 조용한 것은 그 지옥의 문에서 발견된 광기에 반박하는 것 같아요."
rows["456:142244775"]="북바다의 가장자리 일인 실버파인 숲에서, 해안에는 버려진 배가 있다. 이 곳의 서쪽에는 당신이 찾는 것이 있다. 너무 멀리 헤엄쳐서 바다는 피곤함으로 당신을 압도할 것이다. 그것은 바다 바닥에 잠금 상자에 놓여 있으며, 당신이 그것을 주장하기를 기다리고 있다.$B$B이렇게 깊은 곳에 잠수해 나갈 때 도움 없이 살아남을 수 있을 것 같아서, 용기를 좀 더 더 강하게 하라. 거품한 틈은 수중이 이 반을 찾는 사람들에게 숨을 쉬게 해줍니다. 현명하게 사용하세요."
rows["456:993613536"]="안녕, 귀여운, 난 마하르의 마트론 게야$B$B<할머니 게야가 기침을 하고 있다.>$B$B여기 있는다면 포털이 열렸다고 가정할 수 있을 겁니다. 이 곳의 오크들은 대부분 어렸을 적이나 병에 걸려 어둠의 포털을 기억할 수 없었죠.$B$B<조모 게아가 그녀의 주변 오크들을 가리키고 있다.>$B$B많은 사람들이 고아였거나 곧 고아일 것입니다. 네, 블랙핸드는 다른 방법이 없었을 것입니다. 아픈 사람들을 건강하지 않게하십시오. 강한 사람들만이 살아남을 것입니다."
rows["457:1537328656"]="오, 이? <안드윈은 그의 발가락을 가리키고>$b$b가로쉬 헤일스크림은 고대 모그 유물을 이용해 그의 에너지를 불러내려고 했습니다. 저는 그를 막는 방법을 찾았습니다. 하지만 아마 혼자서는 상대해서는 안 되겠죠. 그는 저를 죽은 것으로 생각했고, 실패한 계획의 잔해 아래 묻혀있었죠.$b$b파다렌  ⁇ 이신들은 다시 날 발에 올려놓았지만, 도움 없이 걷기에는 시간이 걸릴 수도 있습니다."
rows["457:2079514372"]="다른 사람들이 스트라톨메에서 스컬지를 싸우는 것을 보는 것이 좋습니다. 왜냐하면 그들은 가장 강한 곳이기 때문입니다.$B$B안녕하세요. 저는 아우리우스입니다. 한때 은손의 paladin였지만, 다른 사람들처럼 그들의 믿음은 흔들렸어요. 저는 은혜에서 떨어졌습니다. 스컬지는 저를 유혹했고 거의 죽음의 기사로 변했습니다.$B$B마침내 내 위험을 감지하고, 이 예배당으로 도망쳤습니다. 그것은 신성한 장소입니다."
rows["457:80117543"]="적어도 좀 설득력 있는 소리 들릴 수 있겠죠.$B$B누아르, 내가 너에게 말하지 않을거야, 하지만 나도 할 수 있어, 왜냐하면 네가도 관련될거야. 맥스나르는 루안 웰드에서 드루이드들을 공격할 계획이야. 그리고 그는 그들을 없애려고 한다.$B$B볼더모크 오그레들과 싸우고 있는 게 너무 나쁘지 않아 다른 전선도 감당할 수 없어$B$B- 어떻게 생각하세요?"
rows["457:837249754"]="망명 전에, 죽음의 날개는 불순종한 자손을 만들고자 노력했습니다. 그들의 자연적인 능력과 능력에 면역이 있을 뿐만 아니라 죽음의 날개의 완전한 통제 아래있을 것입니다.$B$B네파리안은 아버지가 실패한 곳에서는 적어도 부분적으로 성공했을 것 같습니다.$B$B꿈의 모습의 아이세라가 이 혐오스러운 일을 보고 우리에게 행동을 강요했습니다."
rows["458:1068503187"]="우리는 furbolg 종족의 마지막입니다 Timbermaw 부족은 부패하지 않고 있지만 우리는 외부로부터 같은 적대적인 대우를 직면하고 있습니다 대부분의 사람들은 불가능하다고 믿습니다$B$B너무 빨리 적을 만들기 위해 노력하는 사람들에게 분노한 내 형제들은 이제 가까이 다가오는 모든 사람을 공격합니다. 그들은 아무도 믿지 않습니다.$B$B그러나 만일 당신 은 그들과 평화적 인 관계를 맺기 위해 노력 한다면, 그들은 당신 을 동맹자 로 간주 할 수 있을 것 입니다."
rows["458:1181131328"]="내가 '브라티온'이라는 이름을 택한 거야.$b$b내 아버지는 죽음의 날개, 세계 파괴자, 죽음의 측면, 파괴자였지만...$b$b저는 저의 아버지를 사랑하지 않습니다. 그 부패가 제 인종을 파괴했고, 저를 창조하기 위해 제 알을 훔쳐 실험한 붉은 용 비행도 없습니다.$b$b제가... 제 동료가 아니었고, 항상 같은 생각을 가진 영웅들을 찾고 있습니다."
rows["458:1266315717"]="파일론은 어딘가에 데이터를 전송하고 있는 것 같습니다.$b$b기둥을 자세히 살펴보면, 노란색, 빨간색, 녹색의 결정들이 특정한 형식으로 배치된 작은 테이블을 발견하게 됩니다.$B$B큰 노란색의 결정의 원은 두쪽에서 빨간색 결정의 작은 원과 녹색 결정의 다른 원이 접한다.$B$B당신 은 발견 한 것 에 대해 듣기 위해 누군가 의 관심 을 많이 가질 수 있다는 것을 알고, 그 들 이 보는 것 을 주의 깊게 관찰 합니다.\010"
rows["458:149466286"]="한때 인류 땅 에서 가장 큰 금 생산 센터였던 데드 마이닝 은 현재 데피아즈단 에 의해 거주 하고 있으며, 그 들 은 어두운 터널 을 자신 들 의 사적 성지로 바꾼 것 이다. 도둑 들 은 그 들 에게 광물 바닥 에 끔찍한 것 을 짓는 데 도움 을 주기 위해 똑똑 한 괴물 들 을 징집 한 것 이라고 한다. 그러나 그 가 무엇 이 될 수 있는지 는 아직 확실 하지 않는다. 루머 는 데드 마이닝 에 들어가는 길 은 조용 하고 겸손 한 문브룩 마을 을 거쳐 있다는 것 이다.\010"
rows["458:699342210"]="리치 왕를 처리할 때 시간이 지나지 않았습니다. 그는 인간뿐만 아니라 모든 아제로스에게 위협을 합니다.$B$B하지만 전쟁에 나가는 결정은 가볍게 내려서는 안 됩니다. 우리는 노스렌드에 서둘러 바보가 될 것입니다. 리치 왕는 확실히 그러한 행동을 예상했습니다.$B$B우리의 선택은 신중하게 고려되어야 합니다. 우리 군대는 어느 때보다 강력하지만, 전술적으로 부적절한 결정은 우리를 망칠 수 있습니다.$B$B가로쉬가 이해한다면..."
rows["458:782252822"]="처음에는 타란 주에 대한 존경과 존중이 동당을 외부인에게 폐쇄하기로 결정한 것에 대해 의문을 제기하는 것을 금지했습니다.\010그리고 야롱들이 처음 공격했을 때, 전 전투에 집중해서 전선에서 나가서 보병을 보낼 수 없다는 것을 의심하지 못하게 했습니다.\010이제 3명의 샤도파인이 죽고, 한 명은 잡혀... 내 인내심이 더 이상 없어졌어요."
rows["459:1731930940"]="동쪽 펠론은 파란색, 노란색, 녹색 결정들을 받아들이고 있습니다.$B$B이 연구 는 파란색 결정 을 에너지 의 주요 원천 으로 이용 하여 생성 될 수 있는 에너지 에 초점을 맞추고 있습니다. 두 가지 효과 가 있습니다. 하나는 영 에 보너스를 주는 것 이며, 하나는 해로운 방패 를 만드는 것 이다.$B$B크리스탈 파워는 파란색과 녹색의 크리스탈을 필요로 합니다.$B$B크리스탈 스파이어는 파란색과 노란색의 크리스탈을 필요로 합니다. 이것은 공격자에게 피해를 주는 방패를 만들 것입니다.\010"
rows["459:274897686"]="실바나스 여인은 아제로스의 자연 현상들에 대한 조사를 지시했습니다. 그녀는 비밀스러운 과거로부터 배울 수 있는 위대한 것이 있다고 생각합니다.$B$B어떻게 그런 것들을 배웠는지 모르겠지만, 전 그녀를 완전히 신뢰하고 있어 최선을 다할 것입니다.$B$B저는 현재 썰매,  ⁇ 스 등을 연구하고 있습니다. 모든 생물들은 비슷한 메이크업이지만, 환경이 크게 영향을 미칩니다.$B$B내가 당신의 도움을 통해 생물의 샘플을 수집할 수 있습니다.."
rows["459:361889235"]="악마의 진짜 이름에 대한 지식이 그 악마에 대한 어느 정도의 힘을 줄 수 있다고 한다.$B$B페일 이름 책 은 지금까지 존재 한 모든 악마 의 실제 이름 을 담고 있다고 한다. 바디스 는 책 의 구절 을 암기 함 으로, 길단 의 두개골 에서 마시는 일리단 의 자신 의 술 을 견제 할 수 있는 힘 의 근원을 발견 하였다.$B$B이리던의 요청에 따라 바레디스는 이제 카라보르 유적지에서 훈련장을 운영하고 있으며 바레디스를 지도했던 세 명의 마스터들과 함께 운영하고 있습니다."
rows["459:617190057"]="파일론은 어딘가에 데이터를 전송하고 있는 것 같습니다.$b$b기둥을 자세히 살펴보면, 노란색, 빨간색, 녹색의 결정들이 특정한 형식으로 배치된 작은 테이블을 발견하게 됩니다.$B$B큰 파란색의 결정의 원은 양쪽에서 노란색 결정의 작은 원과 녹색 결정의 다른 원이 접한다.$B$B당신 은 발견 한 것 에 대해 듣기 위해 누군가 의 관심 을 많이 가질 수 있다는 것을 알고, 그 들 이 보는 것 을 주의 깊게 관찰 합니다."
