rows["45:99717163"]="모그에 도전할 용기가 있다면 죽을 거야!"
rows["460:1083296078"]="보스의 손에 작은 동전을 던져 보시고, 그 동전을 얻을 수 있는 것을 보세요. 저는 제 일을 좋아합니다. 비록, 작은 불꽃놀이를 하는 스너크를 이 항구로 다시 배치하는 방법을 찾을 수 있다면... 더 잘 상상할 수 없습니다. 하지만, 내 사업 관행에 대해 여기 있지 않은 것을 내걸고 있습니다. 당신은 제펠린을 언더시티로 찾고 있습니다."
rows["460:1539183575"]="맨티드가 공격하고 있고, 우리는 부끄러울 정도로 준비되지 않았습니다.$b$b정상적인 상황에서는 적은 예측할 수 있을 정도입니다. 우리는 다음 대규모의 만티드 공격이 약 10년 후에 일어날 것이라고 예상했습니다.$b$b현재 침략은 거의 \"완전한 규모\"이지만, 여전히 농촌을 어쩔 수 없이 잡을 만큼 강하다. 제 샤도파인은 벽에 이렇게 경호를 기울이지 않았다면, 스톤플로우는 이미 떨어졌을 수도 있습니다."
rows["460:1964342950"]="이 자료의 기록과 비교해 여러분의 시간적 참조를 처리할 수 없습니다.$B$B트로그는 아제로스의 다양한 석기 핵 화합물의 일부 성분을 유지하지만 인지력의 손실은 이 변형을 창조자들에게 받아 들일 수 없게 만든다.$B$B트로그는 표준 바이오매스에 따라 번식한다. 기본적으로 타 트로그를 포함한 다른 모든 것을 소비한다. kanibalism는 창조자들에 의해 받아 들일 수 없다고 간주됩니다."
rows["460:262153227"]="이 자료의 기록과 비교해 여러분의 시간적 참조를 처리할 수 없습니다.$B$B비록 왜성은 지구인의 정신의 대부분을 유지하지만 아제로스돌의 구성에 따라 생체로 되돌리는 것은 매트릭스의 주요 퇴행성입니다. 왜소는 다른 표준 생체와 같은 방법으로 먹고 번식합니다.$B$B창조자들은 왜성자를 수용 가능한 변형으로 보고, 그 자체로 창세에 가치가 있습니다."
rows["460:310137874"]="벽에서 돌아왔어요$B$B거기서 저는 뱀의 척추를 넘어 있는 클라엑시라는 집단에 대한 소문을 들었습니다. 그들은 맨티드 제국에서 분리된 맨티드 장로들의 협의체라고 합니다.$B$B저는 이 마티드의 힘을 직접 봤습니다.$B$B만약 이 소문이 사실이라면, 아마도 이런 Klaxxi와 동맹을 맺고"
rows["460:491322260"]="아라코아족이 본 적 없는 최고의 영웅입니다.$B$B옛날에 스케티스 도시를 자신의 손톱으로 세웠다고 합니다. 그는 우리의 가장 위대한 챔피언이자 수비자였지만, 그는 우리를 떠나버렸어요.$B$B우리는 새로운 주인을 숭배하러 왔는데, 우주에서 우리에게 엄청난 힘과 지위를 약속한 분이십니다.$B$B어떤 사람들은 테록과 루흐마르가 하나라고 말하며 우리가 그를 떠나자마자 그는 우리를 떠나게 되었다고 말하기도 합니다."
rows["461:1512077415"]="세나리우스는 내 편이 돼주기로 했네. 아웃랜드로 간 일리단은 거기서 왕좌에 앉아 있네. 그런데 아서스에게 패한 게 원통했기 때문인지 완전히 미쳐버리고 말았어. 광기에 휩싸여 하루에도 천 번 그때 그 사건을 마음속으로 재연하고 있네. 아서스를 무찌르고 승리하는 상상을 하는 거지. 그는 제정신이 아니야. 친구여, 난 머지않아 우리가 시험을 받게 될 날이 오지 않을까 두렵네. 진아즈샤리의 샘에서처럼 잘해낼 수 있을 자신도 없고 말일세."
rows["461:613301199"]="무한자들은 그들에게 특이하게 미묘한 무언가를 시도하고 있습니다. 그들은 스트라톨메를 죽이기 위해 아르타스가 결정하는 증거를 숨기려고 노력하고 있습니다.$B$B그들의 요원들은 인근의 농촌에 있는 곡물 운송품에 환상적인 마술을 사용해서 정상적인 것처럼 보이게 했습니다.$B$B숨겨진 곡물을 찾아서 이 아카네 디스터퍼를 배포해줘요"
rows["461:794220507"]="그래서... 왕을 죽였어? 내가 이 멍청이들이 당신을 새로운 왕으로 만들지 알았어!$B$B당신이 더 많은 장교들을 살려 두면, 당신의 추물이 더 높을 것 같습니다.  ⁇ 이지는 않더라도 흥미로운 도전을 만들어 줄 것입니다.$B$B또 한 가지... 당신은 우연히 내 열쇠를 찾지 못했습니다, 그렇지?"
rows["462:120577190"]="이 새로운 힘들을 적용하는 데에 학회가 신중한 것이라고 말할 수 있을 것만 있습니다. 남아있는 몇 가지 기록은 그 곳의 마법사들이 미묘한 중독에 대해 걱정했다는 것을 나타냅니다. 오늘날까지 우리 인종이 겪고 있는 문제입니다.$B$B이러한 억제로 인해 메너르의 마법사들은 아즈하라 여왕과 그녀의 높은 지층의 래키에 대항하여 싸웠습니다. 그들은 점점 더 큰 권력을 원하고 야만적인 포기를 했고, 주의를 기울이고 예술의 점점 더 위험한 응용에 몰입했습니다."
rows["462:311806142"]="대장인 푸지크 갈리위크스는 마침내 독소의 불안정한 성격을 연구하고 연구하기 위해 독의 과잉을 그의 탑으로 가져가게 되었고, 마침내 안정적이고 사용할 수 있는 독의 아주 큰 공급을 교환하여 데피아즈단와 독의 비밀을 공유하기로 결정하였다.$B$B데피아즈단의 클라벤 모트웨이크는 Zanzil의 혼합물의 화학적 특성을 변화시키는 작업으로 임무를 맡았다."
rows["462:787708438"]="블랙록 산의 불꽃 속에 새겨진 거대한 요새는 드래곤의 현명한 아들인 죽음의 날개인 네파리안이 상부 스파이어를 장악하고 산의 화산 깊은 곳의 왜성의 소유에 대해 전쟁을 벌이는 때까지 수백 년 동안 악의적인 암흑 철 왜성들이 지배했다. 왜성들은 강력한 불 원자들에 의해 이끌렸다는 것을 깨달은 라그나로스 - 네파리안은 적들을 몰아내고 블랙록 산 전체를 스스로 주장하기로 맹세했다. \010"
rows["463:1390567035"]="오그리마의 설립 이후 많은 시험들이 호드를 시험해왔지만, 우리는 우리를 파괴하려는 모든 사람을 일어서 물리치고 있습니다!$B$B하지만 이것은 내 힘도 이길 수 없는 일이야. 이 전염병으로 인해 내 사람들이 고통받는 것을 보고 깊은 고통을 받는다. 포세이큰 그들의 도움을 위해서$B$B리치 왕은 호드의 전쟁 드럼을 들지만 아직 듣지 않을 것입니다. 먼저, 우리는 스컬지에 대한 복수를 요구하기 전에 우리 백성들을 도와야 합니다."
rows["463:922659574"]="그들이 했던 소음들을 불러라$B$B그 들 은 힘 있는 마술 을 사용 하여 억제 하고 침묵 을 유지 하였고, 그 들 에게 계속 공급 되는 영혼 으로서 함께 유지 되었읍니다. 그러나 그 들 은 여전히 짐승 을 통제 할 수 없었으며, 그 짐승 을 자기 의 뜻 에 따라 굴복 할 수 없었읍니다.$B$B이 필사자들은 다른 전략을 구상하기 시작했고, 하나에 따라 모두 실패했습니다. 그렇게 함으로써 그들은 의식들을 약화시켰고, 우연히 머머에게 작은 자유를 주었습니다.$B$B그게 필요한 전부였어"
rows["464:1456013798"]="다음 선택은 기다리고 있습니다.$B$B당신은 당신의 릴리에게 맹세한 처형자입니다. 당신은 릴리와 당신의 백성의 배신자로서 처형을 위해 당신에게 보낸 사람을 알고 있습니다. 당신은 이 개인을 가장 가까운, 선덕스러운 친구로 알고 있습니다. 그는 신비하게 사라졌습니다. 또한 당신은 그가 유죄 판결을 받은 그 사람의 범죄가 많은 무고한 민간인의 죽음을 초래했다는 것을 알고 있습니다. 당신을 보고 그는 자신의 생명을 구합니다. 그는 더 높은 권위에서 고장되었다고 주장합니다.$B$B선택해"
rows["464:564643515"]="네, 방금 언급한 거니까, 어젯밤은 좀 이상한 걸 봤어요!$B$B저는 이곳 동남쪽의 오래된 트롤 유적들을 지나가고 있었습니다. 저는 실제로 달아나고 있지 않았습니다. 더 나아가 뛰어다니는 것 처럼요. 모래가 너무 뜨겁습니다.$B$B어쨌든, 난 그 헐적들을 지나가던 중, 내가 그곳에 캠프를 설치하는 것을 봤는데, 캠프를 설치하는 게 재밌는 곳 같았어요."
rows["464:745291041"]="그 바람은 이상한 일이 있었습니다. 그것은 멈추지 않았습니다. 몇 주 동안 땅 위로 날아가며, 점점 더 커지고, 점점 더 줄어들었지만, 멈추지 않았습니다. 그 모든 시간 동안 그 목소리가 계속되었습니다.$B$B외로운 시간 은 내 자신을 진정 하고 내 안을 들여다보는 법을 가르쳐 주었다. 이 는 내 정신 을 유지 하기 위해 해왔고. 그때 에 그 목소리 를 이해 하기 시작 했습니다."
rows["465:2127001093"]="제 신념은 여전히 진실이지만, 그것이 저를 앞으로 이끌고 있습니다. 하지만 운명이 완성되기 위해서는$B$B이 임무는 마라우돈의 성당에 들어가야 합니다. 제 사람들이 보호하고 있는 성전입니다.$B$B만약 당신이 나에게 도움이 되는 것을 동의한다면, 당신은 단지 주면만 해야 합니다. 나는 당신에게 내 지침을 담은 문장을 넘겨 줄 것입니다. 그것을 읽고 나의 말을 고려하십시오."
rows["466:1118720486"]="서부 펠론은 빨간색, 녹색, 파란색 결정들을 받아들이고 있습니다.$B$B파이런은 빨간색 결정을 이용해 생성될 수 있는 에너지에 초점을 맞추고 있습니다. 두 가지 효과는 있습니다. 하나는 피해로부터의 보호를 증가시키고 다른 하나는 적의 방어력을 약화시킵니다.$B$B크리스탈 워드는 빨간색과 녹색의 크리스탈을 필요로 합니다.$B$B크리스탈 이이일드는 파란색과 빨간색 크리스탈을 필요로 합니다. 이것은 특정 목표의 갑옷을 낮추는 것입니다."
rows["467:1123510546"]="다음 선택은 기다리고 있습니다.$B$B당신 의 형제 는 당신 이 이미 참여 한 명예 의 군사 계열 에 가입 하려고 합니다. 당신 은 그 의 헌신 과 충성심 을 확신 할 때, 그 의 재능 과 그 의 무겁게 하는 과제를 수행 할 능력 을 의심 하는 것 입니다. 당신 은 그 의 형제 는 당신 과 다른 사람 들 을 위험에 빠뜨리는 계열 의 도전 을 감당 할 수 있을 것 이라고 확신 하지 않음에도 불구하고 당신 의 말 이 그 의 형제 를 허용 하거나 그 를 제외 시키실 것 이라고 확신 합니다.$B$B선택해"
rows["467:925672914"]="사실, 목마귀도 아마 아안키라지에서 벌어질 전쟁에 필요한 것들을 쌓는데 유용할 수 있습니다. 그것은 많은 용도로 사용되는데, 예를 들어, 시리투스 태양 아래 뜨거운 날 동안 아이스크림을 만드는 것, 일부 불쾌한 식물의 효과에 대한 연약, 물 아래에서 호흡하는 것, 피부를 단단히 하는 것, 당신을 빨리 만드는 것, 마력을 되찾는 것,$B$B어 ⁇ 든, 내가 거의 $2047w 여기, 그리고 저는 총 $2048w!"
rows["468:1414813362"]="이 저장소에 저장된 데이터는 실제로 당신의 현명한 선언과 관련이 있습니다.$B$B이 왜기는 아제로스의 석조 구성에 대한 친밀감을 유지하지만, 지구의 합성 매트릭스 내의 고 스트레스 환경적 이상으로 인해 왜기는 표준 지하 매트릭스에서 볼 수있는 기본 바이오매스 구성으로 돌아갑니다.$B$B어고, 왜성 변종은 지구 창조 행렬의 퇴행으로부터 합성되는데,"
rows["468:260259188"]="여기 착륙한 이후로 저는 끔찍한 일들을 보았습니다. 이전에는 가장 어두운 악몽만 सता곤 했었지만,$B$B무투오가 주면$B$B그 안개에서 우리로부터 몇 마일 떨어진 곳에  ⁇ 다르라는 유혈성 존재들이 있습니다. 안개에서 돌아온 사람은 아무도 없고 안개가 들어왔을 때 착륙했던 사람은 거의 없습니다."
rows["468:872209931"]="수직은 여러 종류의 천으로 갑옷, 담요, 옷, 가방, 유역, 그리고 다른 유사한 물건을 만들 수 있습니다. 수직은 죽인 인형적 적들로부터 구입하거나 가져갈 수 있습니다.\010매우 숙련된 도자기도 마법의  ⁇ 을 통해 옷들을 업그레이드 할 수 있습니다.\010마법사들은 종종  ⁇ 꾼이기도 합니다. 왜냐하면 그들이 만든 마법의 물건들을 실망시킬 수 있기 때문입니다."
rows["468:913536568"]="탑의 방어력은 지금 가장 약한 상태이고 순찰, 경비, 감시, 심지어 갈리위크스 자신도 감염되어 있고$B$B내가 네가 그 탑에 들어가고, 네가 나가면, 나는 네가 네 적들의 피에 덮여있으며, 너의 손에 대장부 푸지크 갈리위크의 머리가 있고,\010"
rows["469:259724737"]="발걸음을 차라리!$B$B<보들리는 살아 있는 사람들의 불태운에 대해 숨을 쉬지 않고 불평합니다>$B$B제가 말씀드렸듯이, 왈타락의 영과 유령 암살자들은 그의 시신적인 도용으로 불러오게 되었고 우리를 공격하기 시작했어요. 그 당시 우리는 저항할 수 있는 조건이 없었기 때문에 도망쳤어요.$B$B나머지는 역사입니다."
