rows["470:148978076"]="저는 위대한 힘의 마법사입니다. 저는 제 하루를 학습과 학습 능력의 보존에 관한 마음과 기억을 연구하는 데 보냈습니다. 밤에는 제 서비스가 필요하다는 것을 알려주는 위대한 목소리가 없었다면 지금도 제 연구를 완성하고 있습니다. 저는 짧은 시간 동안만 여기에 있을 것입니다. 여러분의 재능을 무료로 지우기 위해 제 능력을 제공 할 것입니다. 곧 다시 떠날 것입니다. 그리고 여러분은 다시 한 번 당신이 어떤 선택을 하게 되든에 갇히게 될 것입니다."
rows["470:396757648"]="이 요클들이 먹으려 할 때 내가 얻은 자료에 따르면... 여기 발견되는 모든 괴물들을 죽이는 것은 필요 없을 수도 있습니다.$B$B그 전 왕 은 그 의 뒤를 잇는 왕 을 죽였으며, 그 의 왕 을 대신 하였기 때문 에 그 의 장군 들 은 곧바로 그 새로운 왕 에게 충성 을 맹세 하였다.$B$B누가 알겠어요. 당신이 구원하는 괴물이 당신의 것이 될 수도 있습니다."
rows["470:463639008"]="그들은 결코 쉬지 않나요?$B$B만약 우리가 하위 도시 사람들에게 미래를 보장하려면, 그들은 뼈 폐기물보다 더 큰 재앙을 일으키기 전에 그림자 협의회와 대결해야 합니다!$B$B샤트라트 시티의 지도부가 빨리 움직이지 않을 것이기 때문에, 우리는 하위시의 자유민들이$B$B하지만 우리 스파이들이 발견됐어 당신은 험담으로 들어가서 뭘 알아낼 수 있는지 알아볼 때 우린 그림자 협의소의 에이전트를 막을 거야"
rows["470:616129145"]="나는 한때 Twilight's Hammer의 길을 따라왔고, 옛 신들을 부활시키려는 집착으로,$b$b수많은 무고한 희생을 목격한 후, 나는 깨달았다.$b$b난 갇혀있었지만 이제 자유로워졌지만,$b$b용감한 모험가, 아쿠마이를 죽인 대가로 특별한 땅으로 가는 길을 제시해 드릴게요 다르나서스."
rows["471:1105951008"]="난 드루이드 아냐, 군대를 지휘하러 왔어 말푸리온이 전쟁지역 중간에 나무를 심으려고 했기 이상해 보이지만$b$b하지만, 제가 말씀드릴 것은, 그 불의 원자들에겐 그들의 고향의 한가운데에서 자라는 큰 잎겨드랑이 나무가 있다는 생각보다 더 큰 분노가 없습니다. 그 나무가 완전한 크기로 성장할 때,"
rows["471:1837291956"]="히알 산 전투는 이 시간대 중 가장 잘 지켜진 사건 중 하나입니다. 침입자가 그 결과를 바꾸면 그 영향은 역사의 모든 후속 순간으로 확대됩니다.$B$B아스펙트의 최우선 동료로서 다른 동위 용들보다 시간의 흐름에 더 잘 맞추어 있습니다. 최근 저는 하이달 산 전투를 둘러싼 사건에서 나오는 시간 속의 작은 파동을 감지했습니다. 누군가가 또는 무언가가 이 시간선을 바꾸려고 노력하고 있습니다. 그리고 그들은 멈춰야 합니다."
rows["471:779573611"]="베렌은 나로 하여금 브로크인의 지도 역할을 맡길 것을 권했지만 더 중요한 것은 모든 사람들에게 샤머니즘을 가르치라고 요청했었기 때문이었죠.$B$B우리는 그때부터 일부의 편견을 고려하여 이것이 가장 어려운 제안일 것이라는 것을 알고 있었습니다. 빛.$B$B어쨌든, 그건 내 이야기입니다."
rows["472:1929122868"]="예, 지금, 내  ⁇ , 우리 같은 많은 더 많은 o '를 가르치는 데 너무 열망하지 않을거야, 하지만 '우리가 'de 섬의 삶을 유지 할 때까지' 우리를 도와줄거야 'de 섬의 번영을 유지한다.'$B$B난 결코 그렇게 되지 않기를 바랄 뿐이지, 만약 우리가 Cenarion Circle 그룹과 채널을 열고 있다면 $B$B'젠타브라'가 미친듯이  ⁇ 다.$B$B그 밤의 엘프의 얼굴을 보아야 했지"
rows["473:1150475468"]="네가 물어보지 않을거라고 생각하기 시작했어$b$b결국은 다 끝낼 거야 하지만 넌 도울 수 있는 게 많잖아$b$b우리는 거미들이 높은 신진대사를 가지고 있습니다. 그리고 우리가 열심히 일하면만 더 높아집니다. 음식은 항상 환영합니다.$b$b그리고 기름이 있습니다. 이 함정이 너무 복잡합니다. 기어가 방해되는 것에 대해 걱정할 필요가 없습니다.$b$b그 밖엔, 우리를 안전하게 지켜라!$b$b로지는 잠시 기다렸다가 속삭인다$b$b또 다른 일이 있을지도 몰라요"
rows["473:1618668734"]="심문위원은 이 피의 엘프들이 나가란드에서 뭘 하고 있는지 알아내려고 합니다.$B$B의심의 여지없이 어떤 속임수적인 계획이나 조화로 사용...$B$B만약 당신이 우리의 원인을 돕고 이 피의 엘프들을 막으려 한다면, 지금 이 순간 해라에서 북서쪽으로 충돌이 일어나고 있습니다."
rows["473:1675961782"]="우리 군부 장관은 암흑문이 다시 열렸다는 소식을 듣고 즉시 그의 조언자들을 모아 이 용기 있는 탐험을 계획했습니다. 몇몇의 협의자들은 의심을 가지고 있지만, 트롤은 우리 민족의 역사에 대한 새로운 통찰력을 발견할 수 있기를 희망합니다. 그는 이 세계의 잔해 가운데 어딘가에 오크시 민족의 진실한 이야기는 숨겨져 있다고 믿습니다.$B$B제가 가장 어두운 순간에 그 이야기는 전해지지 않을까봐 걱정됩니다."
rows["473:317312815"]="여기, 그린파우 마스터, 전국에서 자이드 펀스 승려라고 알려져 있습니다.$b$b기술, 결단력, 치를 통해 그는 이제 무서운 자이드 스트라이크로 알려진 형태를 마스터했습니다. 적들을 자이드 조각으로 변신시키는 충격이었습니다.$b$b그의 영웅성과 희생이 큰 필요를 겪은 시기에 자이드 숲을 구해줬고, 그와 같은 사람은 이 세상에 다시 볼 수 없을 것입니다.$b$b이 동상은 영원히 평화의 대가를 기억하고 그의 희생은 결코 잊혀지지 않도록 해"
rows["473:895389332"]="권력의 파라곤은 고대 구루바시 제국의 유물입니다. 우리는 그들을 찾고 있습니다. 그들은 우리에게 엄청난 수집 가치를 가지고 있을 뿐만 아니라, 우리는 또한 오래된 제국의 마법의 숨겨진 서명들을 가지고 있다고 믿습니다.$B$B ⁇ 루루브에서 세 종류의 파라곤을 발견할 가능성이 높습니다. 동전, 보석, 원시품. 우리가 찾는 양으로 가져오십시오."
rows["474:1004760523"]="노란색 보안 카드 삽입이 성공했습니다. 보안 레벨 치 단위를 배급합니다.\01001010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001"
rows["474:145123269"]="블래스텐하이머 5000 울트라 캐논 은 최첨단 단인 발사 기기 이다. 용의 속도 가까이에서 유용 한 로드를 전달 하는 이 대포 는 항공 및 연연력 으로 세계적으로 유명한 블래스텐하이머 가족 의 자랑 과 기쁨 이다!$B$B만약 당신이 새처럼 자유롭게 날아다니기 위해 하늘을 날려나가고 싶다면, 샤트라스 시티의 빛의 테라스에서 맥시마 블래스텐하이머를 찾아라. 그녀는 도시 벽 밖의 작은 연못에 있는 목표물을 겨냥해 줄 것이다!"
rows["474:1648175952"]="작은, 한 번의 포털로 주요 호드 또는 얼라이언스 도시.$B$B이 조각들은 모두 함께 하천으로 빨려들었기 때문에 어느 조각이 어디로 갈지 알 수 없습니다. 제가 할 수 있는 가장 좋은 것은 그들이 선레버 포털에서 왔는지 아니면 실버 계약 포털에서 왔는지를 알아내는 것입니다. 양쪽은 그들의 포털 마법을 작은 서명으로 넣는 것을 좋아합니다. 전형적인 엘프스 스파일$B$B내가 당신 분단에 맞는 조각을 팔고, 그들이 안정되면 어디로 가는지는 알아낼 거야"
rows["474:583902047"]="이 성곽의 하위 부분에서 무참한 사람들 중 한 명을 찾아야 합니다. 그 성곽의 하위 부분에서 무장한 승천 봉호를 얻었습니다. 이 물건은 작은 존재 중 한 명에게 큰 영광입니다. 왜냐하면 그것은 상위 성곽에 접근하고 네파리아의 엘리트 경호인 중 한 명으로 되는 첫 번째 단계이기 때문입니다. 블랙핸드 레지온. 그런 물건을 찾아서 내게 돌려보내서 그 특성을 살펴볼 수 있습니다."
rows["474:867431552"]="이것은 제가 조사에서 수집한 정보에서 얻은 것입니다.$B$B두 가지 주요 요금 캠프가 있습니다. 요금 캠프: 우리 서쪽 직후의 증오 캠프 및 요금 캠프: 두려움, 바로 남서쪽. 각 캠프에는 레지온 운송수단, 요금 하나 및 여러 마술 보호 탑이 있습니다. 또한, 캠프들은 화염 경호가 포를 탑재하고 있습니다. 마지막으로, 각 캠프에는 핏 로드 감독자가 있습니다.$B$B그럼 문제가 없겠죠$B$B<알트루이스 웃음>"
rows["475:1015647709"]="보스 바젤플랑지는 더 많은 사람들이 싸우고 싶어하고, 그녀는 그들이 더 잘 싸워야 한다고요.\010\"추진!\" 그녀는 말합니다. \"우리는 그들에게 더 좋은 이유 를 제공 해야 합니다\".\010그래서 그녀는 우리가 이 제플린을 만들도록 했습니다. 싸움의 영광스러운 경상, 당신이 살 수 있는 모든 고급 알코올과 8 또는 더 높습니다.\010 ⁇ 에 올라가고 싶다면 계속 싸움을 이기지 마"
rows["475:211224069"]="사실, 블랙 드래곤 플라이트의 새끼 어머니 는 착각과 속임수를 사용하여 왕실 의 일원 으로 변신 해 왔으며 더 나쁜 것은 현재 스톰윈드의 고령인 볼버 포드라곤 의 통제권을 취했기 때문 이다.$B$B얼라이언스 세력 의 움직임 은 우리 의 머릿 을 긁어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어"
rows["476:1223959266"]="블래스텐하이머 5000 울트라 캐논 은 최첨단 단인 발사 기기 이다. 용의 속도 가까이에서 유용 한 로드를 전달 하는 이 대포 는 항공 및 연연력 으로 세계적으로 유명한 블래스텐하이머 가족 의 자랑 과 기쁨 이다!$B$B만약 당신이 새처럼 자유롭게 날아다니기 위해 하늘을 날아다니고 싶다면 썬더 블러프의 중앙 상승의 남쪽 가장자리에 있는 맥시마 블래스텐하이머를 찾아보세요. 그녀는 당신을 스톤불 호수에서 남쪽으로 목표물을 겨냥하게 할 것입니다."
rows["476:1329721488"]="지금 제가 아르헨티나 십자군 전쟁에 대해 하는 일은 의무의 이행으로만 볼 수 있습니다. 지불, 당신이 원한다면. 하이 ⁇ 로드는 저를 리치 왕의 포착에서 해방시키고 구원의 모든 길을 우리에게 제시했습니다. 그렇게 말하면서, 우리의 방법들이 매우 다르다는 것을 이해해야합니다. 나는 Ebon Blade의 기사들과 아르헨티나 십자군 전쟁의 기초를 얼음관 안에 세울 것을 도울 것입니다. 그리고 우리는 길을 갈라집니다. 지불은 완전히 이루어졌습니다.$B$B다른 운명이 우리를 기다리고 있습니다."
rows["476:1331209555"]="제3차 전쟁 때 시민들 사이에서 마지막으로 나갔을 때부터 얼라이언스는 몇 가지 급격한 변화를 겪었습니다.$B$B<브롤은 발레라를 외면하고 있다.>$B$B...이건 불행히도 피할 수 있었을 겁니다.$B$B불타는 군단와 아제로스에 대한 공격에 집중한 스컬지은 엄청난 힘으로 성장했습니다. 레지옹의 부패와 스컬지의 땅 오염은 동일합니다: 자연 질서의 변동이 끝나는 것입니다."
rows["476:175716781"]="좋은 질문이야$B$B야외에서 사냥을 선호한다면, 플라구랜드, 아즈샤라, 불타는 스텝, 펠우드, 실리투스, 윈터스프링, 심지어 언'고로 크레이터에도 초등적인 동물들이 있습니다.$B$B만약 당신이 위험에 직면해 웃는 타입이라면, 아마도 디레 마우를 방문해야 할 것이다. 나는 그 벽 안에 많은 원자적 변동이 있다는 것을 들었다. 또한 검은바위 나락의 암흑 철 Dwarves에 의해 사용되는 원자적 요소를 찾는 것이 좋습니다."
rows["476:1781794235"]="너 너한테 봐, 너 큰 거고 강하지 않아?$B$B< ⁇ 투자 웃음>$B$B아마 그럴지도 모르지만, 만약 당신이 당신의 힘을 시험하고 싶다면, 피의 반지는 남그란드와 장갈마르시를 나누는 산에 멀리 북쪽으로 있습니다."
rows["476:33488141"]="다음 선택은 기다리고 있습니다.$B$B당신 은 그 들 이 들 을 황폐 히 파괴 하고 있는 끔찍한 짐승 을 이기셨으며 그 귀 를 트로피 로 빼앗아갔읍니다. 그 들 은 나중에 당신 의  ⁇ 이 그 짐승 의 죽음 을 위해 보상 을 제안 한 것 을 알게 되었읍니다. 그리고 당신 이 알고 있는 친절 한 그러나 가난 한 기사 는 그 짐승 의 살해 를 자신 의 것 으로 주장 하고 있습니다. 하지만 당신은 가난 한 기사 는 자신 의 개인적 이익을 위해 거짓말을 하고 있다는 것을 알고 있습니다.$B$B선택해"
rows["476:371866862"]="호드에 더 많은 고통을 야기하려는 당신의 의지를 이해합니다. 하지만 언제 멈출까요? 우리가 썬더 블러프, 아즈하라, 에코 섬을 침공한다면 얼마나 많은 얼라이언스이 죽은 사람들 가운데 있을 것인가? 그리고 우리가 정복된 사람들을 어떻게 통치할 것인가?$b$b판다렌족은 왜 싸우고 있는지 항상 묻습니다. 호드 더 많은 피 흘리는 것은 복수만을 위한 것이고, 그 대가로 복수를 받을 것입니다."
rows["476:453885610"]="며칠 전, 저는 탑에서 내려오는 어두운 에너지의 발광이 바닥을 뚫고 서쪽에서 왔으며 벽을 깨고 거의 완전히 침투했습니다.$b$b아직도 그 흉터가 남아있어요. 농민들의 땅을 망쳤죠.$b$b맨티드 스카우트는 곧 따라갔어요. 그들이 이 공격을 계획했든 아니면 기회를 이용해서든,"
rows["476:587875714"]="내 가장 어두운 시간, 내 존재의 최고상, 내가 실패했다고 믿겠니?$B$B우리를 압도하는 세력의 무단 파괴로부터 도망치면서, 내가 들을 수 있었던 유일한 소리들은 내 군인들의 외침과 내 자신의 심장 박동이었다.$B$B얼마 후, 저는 제 사람들을 구하고 제 명예를 회복할 수 있기를 희망하며 불탄한 땅으로 돌아왔습니다. 대신 저는 잡혀 죽기 까지 박혔습니다.$B$B제 심사위원과 그 후의 고문 과정에서 알게 된 것은 끔찍했습니다."
rows["477:1272055939"]="아탈라이 트롤들이 낳은 신이 이 일에 책임이 있습니다. 우리는 신의 물리적 모습을 파괴하고 성전을 침몰했지만 신은 우리가 예상했던 것보다 훨씬 강했습니다. 부패의 씨앗은 깊게 흘러들어갔고, 모든 것을 왜곡했습니다.$B$B에라니쿠스는 이 부패의 무지한 희생자였고, 우리는 그 힘을 과소평가하는 것 입니다."
rows["477:232127823"]="내 이야기? 부탁하는 건 친절한데요.$B$B오래전, 드레너 행성에서, 그 유적이 현재 아웃랜드로 알려져 있습니다. 드레네이족은 모두 평화롭게 살았지만, 그 다음에는 불타는 군단가 와서, 그들은 그들의 펠 마법을 통해 오크들을 부패시켰다.$B$B다른 선택의 여지가 없었고 살아남기 위해 싸웠지만 이 악성 에너지에 노출된 것은 우리 중 몇몇에게 끔찍한 영향을 미쳤고 시간이 지남에 따라 우리를 나 같은 깨진 사람으로 변시켰습니다.$B$B계속 해야겠어요?"
rows["478:1729567848"]="왜 내려다보죠?$B$B ⁇ 돌이족은 오랜 전통을 가진 유화족이라는 걸 알도록 하겠습니다.$B$B그래, 그건 말이야!$B$B아제로스의 모든 곳이나 그 밖의 곳에는 더 훌륭한 수학자 없습니다!$B$B저는 지금 연습생이라는 타이틀을 가지고 있을지도 모르지만, 제 능력은 그 누구보다 크지 않습니다.$B$B물론, 어쩌면 당신이 단지 나를 돕기 위해 여기에 왔을지도 몰라?$B$B<미미미성  ⁇ 은 자부심을 가지고 웃는다.>"
rows["478:1831327146"]="이건 왜, 조문이야?$b$b뭐, 숨기게 아무것도 없어요. 내 기록을 살펴볼게요. 지난 주에 난 미너 중위에게  ⁇ 옷을 팔았는데, 그건 이상한 것 같았어요. 또 다른 것은... 마구스 비스프는 몇 십 개의 가죽 주머니를 샀어요. 그 이유는 없었어요. 오, 버링엄 형제는 하드브렌치 히데웨이 여행에 수영복을 준비하러 왔어요. 그 정도야.$b$b이제 괜찮다면, 고객들이 있어요!"
rows["478:1877940158"]="우리가 알고 있던 모든 것, 우리가 알고 있던 모든 것, 우리가 알고 있을 모든 것$B$B결국 바로프 가족들과의 접촉이 끊어졌고 결국 가계로부터 분리되었습니다. 다른 종들은 무슨 일이 있었는지 몰랐지만, 외치는 소리들, 고문 외치는 소리들만 들었습니다.$B$B루시엔 과 저는 갈 곳 이 없다는 것을 알고서 방 에 숨어들게 되었습니다. 낮 에 학교 는 비교적 조용 할 때, 루시엔 은 음식 과 음료 를 찾아내기 위해 간구 로 밖으로 나갔습니다."
rows["478:808394494"]="내가 피오레스 일다누브, 귀에 닿는 가장 위대한 마지스트, 언더시티.$B$B제 위대함은 이 개혁 기간 동안만 느껴질 것입니다. 왕실의 블리자드 하우스가 이전에는 볼 수 없고, 들리지 않고, 느낄 수도 없는$B$B정말 대단할 겁니다. 사실, 시간과 공간의 구조가 스스로 변화해 이 세상의 주민들을 새로운 풍요로운 시대에 몰아넣을 것입니다."
rows["47:1000610481"]="칼림도어의 힘은 그들의 진전을 막으리니"
rows["47:1003721388"]="성공하면 더욱더 강력한 힘을 맛보게 될 것이다!"
rows["47:1006940859"]="용사들이여, 겨울의 장막이 너희를 보호하리라!"
rows["47:1007468553"]="저한테 봐요, 내가 주문한 것 같나요?"
rows["47:1010335482"]="저는 겸손히 빛의 뜻에 전념합니다."
